join public.tasks t on t.slug = v.task_slug and t.source = 'seed'
join public.skills s on s.slug = v.skill_slug
on conflict do nothing;

insert into private.task_solutions (task_id, correct_option_ids, explanation, solution_files)
select t.id, v.correct_option_ids, v.explanation, v.solution_files from (values
  ('ng-computed-signal', array['b']::text[], '{"en":"`computed` tracks the signals it reads. When `count` changes, `double` is marked stale and recomputes lazily the next time it''s read, so it returns 10. Computed signals are read-only, but reading them is always allowed.","uk":"`computed` відстежує сигнали, які читає. Коли `count` змінюється, `double` позначається застарілим і ліниво перераховується при наступному читанні, тож повертає 10. Обчислювані сигнали лише для читання, але читати їх можна завжди."}'::jsonb, null::jsonb),
  ('ng-outside-zone', array['a']::text[], '{"en":"zone.js triggers change detection when async work that started inside the Angular zone finishes. Libraries initialised outside the zone (often on purpose, with `runOutsideAngular`, for performance) call back without Angular knowing. Re-enter the zone with `ngZone.run()`, or update a signal, which schedules change detection by itself.","uk":"zone.js запускає виявлення змін, коли завершується асинхронна робота, розпочата в зоні Angular. Бібліотеки, ініціалізовані поза зоною (часто навмисно, через `runOutsideAngular`, заради швидкодії), викликають колбеки без відома Angular. Поверніться в зону через `ngZone.run()` або оновіть сигнал — він сам запланує виявлення змін."}'::jsonb, null::jsonb),
  ('ng-effect-batching', array['b']::text[], '{"en":"Setting a signal only marks its dependents dirty. Effects are scheduled and run later, as part of change detection, not synchronously inside `set()`. By then the value is 2, so the effect runs once and logs `2`. Don''t use effects to observe every intermediate value; they see the latest state.","uk":"Встановлення сигналу лише позначає залежних як «брудних». Ефекти плануються й виконуються пізніше, у межах виявлення змін, а не синхронно всередині `set()`. На той момент значення вже 2, тож ефект виконається один раз і виведе `2`. Не використовуйте ефекти, щоб спостерігати кожне проміжне значення: вони бачать останній стан."}'::jsonb, null::jsonb),
  ('ng-binding-syntax', array['b']::text[], '{"en":"Parentheses bind to events (view → class). Square brackets bind properties (class → view), interpolation renders text, and `*` marks structural directives.","uk":"Круглі дужки прив''язують події (вигляд → клас). Квадратні дужки прив''язують властивості (клас → вигляд), інтерполяція виводить текст, а `*` позначає структурні директиви."}'::jsonb, null::jsonb),
  ('ng-oninit-vs-constructor', array['a']::text[], '{"en":"The constructor is for DI and simple field setup. Angular sets inputs after construction and then calls `ngOnChanges` and `ngOnInit`, so logic that depends on inputs (like loading by `id`) belongs in `ngOnInit`.","uk":"Конструктор призначений для DI та простого налаштування полів. Angular встановлює вхідні дані після створення, а потім викликає `ngOnChanges` і `ngOnInit`, тож логіка, що залежить від вхідних даних (як-от завантаження за `id`), належить до `ngOnInit`."}'::jsonb, null::jsonb),
  ('ng-onpush-mutation', array['a']::text[], '{"en":"OnPush checks a component when an input gets a new reference (or for its own events, async pipe emissions and `markForCheck`). Mutating the array keeps the reference, so the child is skipped. Use `this.items = [...this.items, item]`.","uk":"OnPush перевіряє компонент, коли вхідні дані отримують нове посилання (а також для власних подій, значень async pipe і `markForCheck`). Мутація масиву зберігає посилання, тож дитину пропускають. Використовуйте `this.items = [...this.items, item]`."}'::jsonb, null::jsonb),
  ('ng-provider-scope', array['b']::text[], '{"en":"Component-level providers create a new injector per component instance, so each instance (and its children) gets its own service. `providedIn: \"root\"` creates one app-wide singleton instead.","uk":"Провайдери на рівні компонента створюють новий інжектор для кожного екземпляра, тож кожен екземпляр (і його нащадки) отримує власний сервіс. `providedIn: \"root\"` натомість створює один синглтон на весь застосунок."}'::jsonb, null::jsonb),
  ('ng-async-pipe', array['a', 'b']::text[], '{"en":"The async pipe subscribes, unsubscribes on destroy and calls `markForCheck`, so it works well with OnPush. Each `| async` is a separate subscription, though: a cold HTTP observable used twice fires two requests unless you share it (e.g. `shareReplay`). Errors still need handling.","uk":"async pipe підписується, відписується при знищенні й викликає `markForCheck`, тож добре працює з OnPush. Але кожен `| async` є окремою підпискою: холодний HTTP-observable, використаний двічі, зробить два запити, якщо його не поділити (наприклад, `shareReplay`). Помилки все одно треба обробляти."}'::jsonb, null::jsonb),
  ('ng-quantity-stepper', null::text[], '{"en":"The stepper is a controlled component: it only emits the requested value, and the parent writes it back through `[value]`. `[disabled]` bindings reflect the limits, and clamping in `change()` guards against out-of-range emits.","uk":"Лічильник є керованим компонентом: він лише надсилає бажане значення, а батько повертає його через `[value]`. Прив''язки `[disabled]` відображають межі, а обмеження в `change()` захищає від значень поза діапазоном."}'::jsonb, '{"/src/app/stepper.component.ts":"import { Component, EventEmitter, Input, Output } from \"@angular/core\";\n\n@Component({\n  selector: \"app-stepper\",\n  template: `\n    <button type=\"button\" aria-label=\"Decrease\" (click)=\"change(-1)\" [disabled]=\"value <= min\">−</button>\n    <span data-testid=\"value\">{{ value }}</span>\n    <button type=\"button\" aria-label=\"Increase\" (click)=\"change(1)\" [disabled]=\"value >= max\">+</button>\n  `,\n})\nexport class StepperComponent {\n  @Input() value = 0;\n  @Input() min = 0;\n  @Input() max = 10;\n  @Output() valueChange = new EventEmitter<number>();\n\n  change(delta: number) {\n    const next = Math.min(this.max, Math.max(this.min, this.value + delta));\n    if (next !== this.value) this.valueChange.emit(next);\n  }\n}\n"}'::jsonb),
  ('arr-fill-shared', array['b']::text[], '{"en":"`fill([])` evaluates `[]` once and puts the same array reference in every slot, so pushing into one row changes all of them. Create a new array per slot with `Array.from({ length: 3 }, () => [])`.","uk":"`fill([])` обчислює `[]` один раз і кладе те саме посилання в кожну комірку, тож додавання в один рядок змінює всі. Створюйте новий масив для кожної комірки: `Array.from({ length: 3 }, () => [])`."}'::jsonb, null::jsonb),
  ('arr-holes-map', array['c']::text[], '{"en":"`Array(3)` creates a sparse array with length 3 but no elements. `map`, `forEach` and `filter` skip holes, so the callback never runs and the result is still sparse. Use `Array.from({ length: 3 }, (_, i) => i)` or `[...Array(3).keys()]`.","uk":"`Array(3)` створює розріджений масив довжиною 3 без елементів. `map`, `forEach` і `filter` пропускають «дірки», тож колбек не викликається, а результат лишається розрідженим. Використовуйте `Array.from({ length: 3 }, (_, i) => i)` або `[...Array(3).keys()]`."}'::jsonb, null::jsonb),
  ('arr-splice-in-foreach', array['b']::text[], '{"en":"`forEach` walks indexes 0, 1, 2… over the live array. Removing 2 at index 0 shifts 4 into index 0, but the next visit is index 1 (now 6), so 4 is never checked. Removing 6 shifts 7 to index 1, and the loop ends because the length is now 2. Use `nums = nums.filter((n) => n % 2 !== 0)`, or loop backwards if you must mutate.","uk":"`forEach` проходить індекси 0, 1, 2… живого масиву. Видалення 2 з індексу 0 зсуває 4 на індекс 0, але наступний відвіданий індекс — 1 (тепер це 6), тож 4 не перевіряється. Видалення 6 зсуває 7 на індекс 1, і цикл завершується, бо довжина тепер 2. Використовуйте `nums = nums.filter((n) => n % 2 !== 0)` або, якщо мусите змінювати масив, ідіть з кінця."}'::jsonb, null::jsonb),
  ('str-run-length', null::text[], '{"en":"Encoding uses two pointers: `j` scans to the end of the current run, and the run length is `j - i`. Decoding reads a letter followed by an optional number. A regex with `matchAll` handles multi-digit counts cleanly, and `repeat` expands each run. Building a string with `+=` is fine here; for very large inputs, push parts into an array and `join` once.","uk":"Кодування використовує два вказівники: `j` доходить до кінця поточної серії, а довжина серії — `j - i`. Декодування читає літеру й необов''язкове число після неї. Регулярний вираз із `matchAll` охайно обробляє багатозначні лічильники, а `repeat` розгортає кожну серію. Побудова рядка через `+=` тут підходить; для дуже великих даних збирайте частини в масив і один раз робіть `join`."}'::jsonb, '{"/src/rle.ts":"export function encode(text: string): string {\n  let out = \"\";\n  for (let i = 0; i < text.length; ) {\n    let j = i;\n    while (j < text.length && text[j] === text[i]) j++;\n    const run = j - i;\n    out += text[i] + (run > 1 ? String(run) : \"\");\n    i = j;\n  }\n  return out;\n}\n\nexport function decode(encoded: string): string {\n  let out = \"\";\n  for (const [, letter, count] of encoded.matchAll(/([a-zA-Z])(\\d*)/g)) {\n    out += letter.repeat(count ? Number(count) : 1);\n  }\n  return out;\n}\n"}'::jsonb),
  ('arr-default-sort', array['b']::text[], '{"en":"Without a comparator, elements are converted to strings and compared by UTF-16 code units, so \"10\" < \"100\" < \"5\". Use `(a, b) => a - b` for numbers.","uk":"Без компаратора елементи перетворюються на рядки й порівнюються за кодами UTF-16, тому \"10\" < \"100\" < \"5\". Для чисел використовуйте `(a, b) => a - b`."}'::jsonb, null::jsonb),
  ('arr-mutating-methods', array['a', 'c', 'e']::text[], '{"en":"`sort`, `splice` and `reverse` change the array in place. `toSorted` and `slice` return new arrays and leave the original untouched, which is what you want for React or Redux state.","uk":"`sort`, `splice` і `reverse` змінюють масив на місці. `toSorted` і `slice` повертають нові масиви й не чіпають вихідний, що й потрібно для стану React чи Redux."}'::jsonb, null::jsonb),
  ('arr-reduce-initial', array['c']::text[], '{"en":"Without an initial value, `reduce` uses the first element as the accumulator, which doesn''t exist for an empty array, so it throws. Always pass one: `reduce((s, x) => s + x.price, 0)`.","uk":"Без початкового значення `reduce` бере перший елемент як акумулятор, а в порожньому масиві його немає, тож метод кидає помилку. Завжди передавайте значення: `reduce((s, x) => s + x.price, 0)`."}'::jsonb, null::jsonb),
  ('arr-dedupe-complexity', array['a']::text[], '{"en":"`indexOf` inside `filter` is O(n²). A Set keeps insertion order and gives O(1) membership, so `[...new Set(items)]` is O(n). Sorting first is O(n log n), loses the original order and mutates `items`.","uk":"`indexOf` усередині `filter` дає O(n²). Set зберігає порядок вставки й перевіряє наявність за O(1), тож `[...new Set(items)]` працює за O(n). Попереднє сортування дає O(n log n), втрачає початковий порядок і змінює `items`."}'::jsonb, null::jsonb),
  ('str-emoji-reverse', array['a']::text[], '{"en":"Characters outside the Basic Multilingual Plane take two UTF-16 code units. `split(\"\")` separates them, and reversing swaps the halves into invalid sequences. `[...s]` (or `Array.from(s)`) iterates by code points. Grapheme clusters such as flags or skin tones need `Intl.Segmenter`.","uk":"Символи поза базовою багатомовною площиною займають дві кодові одиниці UTF-16. `split(\"\")` розділяє їх, а розворот міняє половинки місцями й дає некоректні послідовності. `[...s]` (або `Array.from(s)`) ітерує за кодовими точками. Для графемних кластерів, як-от прапорів чи відтінків шкіри, потрібен `Intl.Segmenter`."}'::jsonb, null::jsonb),
  ('str-group-anagrams', null::text[], '{"en":"Map each word to a canonical signature: its lower-cased letters, sorted. A Map from signature to group preserves insertion order, so groups come out in first-appearance order. Sorting each word costs O(k log k), so the total is O(n·k log k). A 26-letter count vector would make it O(n·k).","uk":"Зіставте кожне слово з канонічним підписом: його літери в нижньому регістрі, відсортовані. Map від підпису до групи зберігає порядок вставки, тож групи йдуть у порядку першої появи. Сортування кожного слова коштує O(k log k), разом O(n·k log k). Вектор лічильників із 26 літер дав би O(n·k)."}'::jsonb, '{"/src/anagrams.ts":"function signature(word: string) {\n  return [...word.toLowerCase().replace(/[^\\p{L}]/gu, \"\")].sort().join(\"\");\n}\n\nexport function groupAnagrams(words: string[]): string[][] {\n  const groups = new Map<string, string[]>();\n  for (const word of words) {\n    const key = signature(word);\n    const group = groups.get(key);\n    if (group) group.push(word);\n    else groups.set(key, [word]);\n  }\n  return [...groups.values()];\n}\n"}'::jsonb),
  ('async-return-value', array['b']::text[], '{"en":"An `async` function always returns a Promise. A returned value becomes the fulfilment value, and a thrown error becomes a rejection. Read the value with `await getAnswer()` or `.then()`.","uk":"`async`-функція завжди повертає Promise. Повернене значення стає значенням виконання, а кинута помилка — відхиленням. Отримайте значення через `await getAnswer()` або `.then()`."}'::jsonb, null::jsonb),
  ('async-all-fail-fast', array['b']::text[], '{"en":"`Promise.all` rejects as soon as any input rejects, but promises are not cancellable: the other requests continue and their results are dropped. `Promise.all` subscribes to every input, so their later rejections are not reported as unhandled. To actually stop the work, pass an `AbortSignal` and abort it in a `catch`.","uk":"`Promise.all` відхиляється, щойно відхиляється будь-який вхід, але проміси не скасовуються: решта запитів триває, а їхні результати відкидаються. `Promise.all` підписується на кожен вхід, тож пізніші відхилення не стають необробленими. Щоб справді зупинити роботу, передайте `AbortSignal` і скасуйте його в `catch`."}'::jsonb, null::jsonb),
  ('async-return-promise-ticks', array['b']::text[], '{"en":"Resolving the async function''s promise with another promise isn''t immediate: it schedules a job that calls the inner promise''s `then`, which takes extra microtask ticks before the outer promise settles. `Promise.resolve(\"b\").then` needs only one tick, so `b` wins. `return await` or returning a plain value avoids the extra ticks, but don''t build logic on tick counting.","uk":"Виконання промісу async-функції іншим промісом не миттєве: планується завдання, що викликає `then` внутрішнього промісу, і це займає додаткові мікрозавдання, перш ніж зовнішній проміс завершиться. `Promise.resolve(\"b\").then` потребує лише одного такту, тож `b` перший. `return await` або повернення звичайного значення прибирає зайві такти, але не будуйте логіку на підрахунку тактів."}'::jsonb, null::jsonb),
  ('async-retry-backoff', null::text[], '{"en":"A loop with `try { return await task(attempt) }` keeps the code flat: `return await` is needed so a rejection lands in this `catch`. After attempt n the wait is `base · 2^(n-1)`. Rethrowing the caught error preserves the last failure. In production, add random jitter so many clients don''t retry in lockstep, and only retry errors that can succeed later (timeouts, 429, 5xx).","uk":"Цикл із `try { return await task(attempt) }` тримає код пласким: `return await` потрібен, щоб відхилення потрапило в цей `catch`. Після спроби n затримка — `base · 2^(n-1)`. Повторне кидання впійманої помилки зберігає останню невдачу. У продакшні додайте випадковий розкид, щоб багато клієнтів не повторювали синхронно, і повторюйте лише помилки, що можуть минути (тайм-аути, 429, 5xx)."}'::jsonb, '{"/src/retry.ts":"export type RetryOptions = {\n  retries: number;\n  baseDelayMs: number;\n  shouldRetry?: (error: unknown) => boolean;\n};\n\nconst sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));\n\nexport async function retry<T>(task: (attempt: number) => Promise<T>, options: RetryOptions): Promise<T> {\n  const { retries, baseDelayMs, shouldRetry = () => true } = options;\n  for (let attempt = 1; ; attempt++) {\n    try {\n      return await task(attempt);\n    } catch (error) {\n      if (attempt > retries || !shouldRetry(error)) throw error;\n      await sleep(baseDelayMs * 2 ** (attempt - 1));\n    }\n  }\n}\n"}'::jsonb),
  ('async-event-loop-order', array['b']::text[], '{"en":"Synchronous code runs first (1, 4). Then all microtasks run (the promise callback: 3), and only then the next macrotask (the timer: 2).","uk":"Спершу виконується синхронний код (1, 4). Потім усі мікрозадачі (колбек промісу: 3), і лише тоді наступна макрозадача (таймер: 2)."}'::jsonb, null::jsonb),
  ('async-all-settled', array['b']::text[], '{"en":"`allSettled` waits for every promise and reports `{status, value|reason}` for each, so one failure doesn''t hide the others. `all` rejects on the first error; `race`/`any` give you only one result.","uk":"`allSettled` чекає на кожен проміс і повертає `{status, value|reason}` для всіх, тож одна помилка не приховує решту. `all` відхиляється на першій помилці; `race`/`any` дають лише один результат."}'::jsonb, null::jsonb),
  ('async-foreach-await', array['a']::text[], '{"en":"Each callback is async and returns a promise that `forEach` drops. Use `await Promise.all(files.map(upload))` for parallel uploads, or `for (const f of files) await upload(f)` for sequential ones.","uk":"Кожен колбек асинхронний і повертає проміс, який `forEach` відкидає. Використовуйте `await Promise.all(files.map(upload))` для паралельних завантажень або `for (const f of files) await upload(f)` для послідовних."}'::jsonb, null::jsonb),
  ('async-sequential-vs-parallel', array['b']::text[], '{"en":"The second request starts only after the first finishes. Starting both before awaiting overlaps the network waits: `const [user, orders] = await Promise.all([getUser(), getOrders()])`. A single thread doesn''t matter, because the waiting happens in the network stack.","uk":"Другий запит стартує лише після завершення першого. Якщо запустити обидва до `await`, очікування мережі перекриваються: `const [user, orders] = await Promise.all([getUser(), getOrders()])`. Один потік не заважає, бо очікування відбувається в мережевому стеку."}'::jsonb, null::jsonb),
  ('async-promise-any', array['b']::text[], '{"en":"`race` settles with whichever promise settles first, including a fast failure. `any` waits for the first fulfilment and only rejects (with `AggregateError`) when every promise rejected.","uk":"`race` завершується тим промісом, що завершився першим, навіть швидкою помилкою. `any` чекає першого успіху й відхиляється (з `AggregateError`) лише коли відхилено всі проміси."}'::jsonb, null::jsonb),
  ('async-map-with-concurrency', null::text[], '{"en":"Start `limit` workers. Each one repeatedly claims the next index and awaits `fn`. Because JavaScript runs on one thread, `next++` can''t race. Writing into `results[index]` keeps the input order, and `Promise.all(workers)` rejects as soon as any worker throws.","uk":"Запустіть `limit` воркерів. Кожен по черзі забирає наступний індекс і чекає на `fn`. Оскільки JavaScript працює в одному потоці, `next++` не має гонки. Запис у `results[index]` зберігає порядок вхідних даних, а `Promise.all(workers)` відхиляється, щойно будь-який воркер кидає помилку."}'::jsonb, '{"/src/mapWithConcurrency.ts":"export async function mapWithConcurrency<T, R>(\n  items: T[],\n  limit: number,\n  fn: (item: T, index: number) => Promise<R>,\n): Promise<R[]> {\n  const results = new Array<R>(items.length);\n  let next = 0;\n\n  async function worker() {\n    while (next < items.length) {\n      const index = next++; // claimed synchronously: no two workers take the same index\n      results[index] = await fn(items[index], index);\n    }\n  }\n\n  const workers = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, worker);\n  await Promise.all(workers);\n  return results;\n}\n"}'::jsonb),
  ('bigo-two-inputs', array['c']::text[], '{"en":"The inner loop runs m times for each of the n outer iterations: O(n · m). Calling it O(n²) hides that the inputs are independent; if there are only a few coupons, this is effectively linear in n. Putting the coupon codes in a `Set` first would make it O(n + m).","uk":"Внутрішній цикл виконується m разів для кожної з n зовнішніх ітерацій: O(n · m). Назва O(n²) приховує, що входи незалежні; якщо купонів лише кілька, це фактично лінійно за n. Якщо спершу покласти коди купонів у `Set`, вийде O(n + m)."}'::jsonb, null::jsonb),
  ('bigo-recurrence', array['b']::text[], '{"en":"The work per level is n + n/2 + n/4 + …, a geometric series that sums to less than 2n, so T(n) = O(n). Compare merge sort, T(n) = 2T(n/2) + n: there each level does n work in total across log n levels, giving O(n log n). Quickselect''s average case follows the T(n/2) + n pattern.","uk":"Робота на рівнях — n + n/2 + n/4 + …, геометрична прогресія із сумою менше 2n, тож T(n) = O(n). Порівняйте з сортуванням злиттям, T(n) = 2T(n/2) + n: там кожен рівень загалом виконує n роботи на log n рівнях, що дає O(n log n). Середній випадок quickselect відповідає шаблону T(n/2) + n."}'::jsonb, null::jsonb),
  ('bigo-output-size', array['b']::text[], '{"en":"There are 2ⁿ subsets, and the function materialises each one as an array: `[...s, item]` copies up to n elements, so the total work (and output size) is O(n · 2ⁿ). When the output itself is large, the complexity can never be lower than the size of the output.","uk":"Існує 2ⁿ підмножин, і функція створює кожну як масив: `[...s, item]` копіює до n елементів, тож загальна робота (і розмір виходу) — O(n · 2ⁿ). Коли вихід сам великий, складність не може бути меншою за його розмір."}'::jsonb, null::jsonb),
  ('bigo-nearby-duplicate', null::text[], '{"en":"Remember the most recent index of each value in a `Map`. For each position, a single O(1) average lookup tells you whether the same value appeared within the last k positions; keeping only the latest index is enough, because it is always the closest one. That''s O(n) time and O(n) space. A sliding-window `Set` of the last k values works too and uses O(k) memory.","uk":"Запам''ятовуйте останній індекс кожного значення в `Map`. Для кожної позиції один пошук за O(1) у середньому каже, чи траплялося те саме значення в межах останніх k позицій; достатньо зберігати лише останній індекс, бо він завжди найближчий. Це O(n) часу й O(n) пам''яті. Підходить і ковзне вікно `Set` з останніх k значень, що використовує O(k) пам''яті."}'::jsonb, '{"/src/nearby.ts":"export function hasNearbyDuplicate(values: number[], k: number): boolean {\n  const lastIndex = new Map<number, number>();\n  for (let i = 0; i < values.length; i++) {\n    const previous = lastIndex.get(values[i]);\n    if (previous !== undefined && i - previous <= k) return true;\n    lastIndex.set(values[i], i);\n  }\n  return false;\n}\n"}'::jsonb),
  ('bigo-nested-loops', array['c']::text[], '{"en":"The inner loop runs up to n times for each of the n outer iterations: about n²/2 comparisons, which is O(n²), since constants are dropped.","uk":"Внутрішній цикл виконується до n разів для кожної з n зовнішніх ітерацій: близько n²/2 порівнянь, тобто O(n²), бо константи відкидаються."}'::jsonb, null::jsonb),
  ('bigo-includes-in-loop', array['b']::text[], '{"en":"`includes` scans the whole array, so it''s O(m) per user and O(n·m) overall. A Set gives O(1) average membership: O(m) to build it plus O(n) to filter.","uk":"`includes` переглядає весь масив, тобто O(m) на кожного користувача й O(n·m) загалом. Set дає перевірку наявності в середньому за O(1): O(m) на побудову плюс O(n) на фільтрацію."}'::jsonb, null::jsonb),
  ('bigo-halving', array['b']::text[], '{"en":"`n` halves every iteration, so the loop runs about log₂(n) times before reaching 0, the same reason binary search is O(log n).","uk":"`n` зменшується вдвічі на кожній ітерації, тож цикл виконується приблизно log₂(n) разів, доки не дійде до 0. З тієї самої причини бінарний пошук має O(log n)."}'::jsonb, null::jsonb),
  ('bigo-amortized-push', array['a']::text[], '{"en":"When capacity runs out, the engine allocates a bigger buffer (typically growing geometrically) and copies the elements. Those rare O(n) steps are spread over many cheap pushes, so n pushes cost O(n) in total.","uk":"Коли місткість закінчується, рушій виділяє більший буфер (зазвичай зі зростанням у геометричній прогресії) і копіює елементи. Ці рідкісні кроки O(n) розподіляються між багатьма дешевими push, тож n push разом коштують O(n)."}'::jsonb, null::jsonb),
  ('bigo-space-recursion', array['d']::text[], '{"en":"The recursion is n deep, and each live frame holds its own slice of size n−k, so the total memory is n + (n−1) + … = O(n²) (time is O(n²) too). Passing an index instead of slicing brings it to O(n) stack, or O(1) as a loop.","uk":"Глибина рекурсії n, і кожен активний кадр тримає власний зріз розміру n−k, тож загалом пам''ять n + (n−1) + … = O(n²) (час теж O(n²)). Передача індексу замість зрізу дає O(n) стеку, а цикл дає O(1)."}'::jsonb, null::jsonb),
  ('browser-intersection-observer', array['b']::text[], '{"en":"`IntersectionObserver` lets the browser compute visibility asynchronously and calls you only when the sentinel crosses the threshold. `rootMargin: \"400px\"` starts loading before the user actually reaches the end. Scroll handlers that read layout run on every scroll event and can force synchronous layout.","uk":"`IntersectionObserver` дозволяє браузеру асинхронно обчислювати видимість і викликає вас лише тоді, коли маркер перетинає поріг. `rootMargin: \"400px\"` починає завантаження ще до того, як користувач дійде до кінця. Обробники прокрутки, що читають розмітку, виконуються на кожну подію й можуть змушувати синхронний перерахунок макета."}'::jsonb, null::jsonb),
  ('browser-storage-event', array['c']::text[], '{"en":"The `storage` event fires in other documents of the same origin that share the storage area, never in the one that made the change. That makes it a simple cross-tab sync channel (log out everywhere, theme changes). For richer messaging, use `BroadcastChannel`.","uk":"Подія `storage` спрацьовує в інших документах того самого походження, що мають спільне сховище, але ніколи в тому, який зробив зміну. Тож це простий канал синхронізації між вкладками (вихід усюди, зміна теми). Для багатшого обміну повідомленнями використовуйте `BroadcastChannel`."}'::jsonb, null::jsonb),
  ('browser-sw-waiting', array['b']::text[], '{"en":"A new service worker installs in the background and then waits while any client is still controlled by the old one. A reload doesn''t release the client, because the old page stays alive until the new one commits. Show an \"Update available\" prompt that calls `skipWaiting()` (then reload on `controllerchange`), or call `skipWaiting()` if your caches are backwards compatible.","uk":"Новий service worker встановлюється у фоні й чекає, доки хоч один клієнт ще керується старим. Перезавантаження не звільняє клієнта, бо стара сторінка живе, доки нова не завантажиться. Покажіть підказку «Доступне оновлення», що викликає `skipWaiting()` (і перезавантажте на `controllerchange`), або викликайте `skipWaiting()`, якщо ваші кеші зворотно сумісні."}'::jsonb, null::jsonb),
  ('browser-build-url', null::text[], '{"en":"`new URL(base)` parses the existing query into `url.searchParams`, which handles all the encoding (`application/x-www-form-urlencoded`, so spaces become `+`). `delete` and then `append` gives replace-then-repeat semantics for arrays, and `set` replaces a single value. String concatenation breaks as soon as a value contains `&`, `#` or `=`.","uk":"`new URL(base)` розбирає наявний запит у `url.searchParams`, що бере на себе все кодування (`application/x-www-form-urlencoded`, тож пробіли стають `+`). `delete`, а потім `append` дають для масивів семантику «замінити, потім повторити», а `set` замінює одне значення. Конкатенація рядків ламається, щойно значення містить `&`, `#` або `=`."}'::jsonb, '{"/src/build-url.ts":"export type QueryValue = string | number | boolean | null | undefined | (string | number)[];\n\nexport function buildUrl(base: string, params: Record<string, QueryValue>): string {\n  const url = new URL(base);\n  for (const [key, value] of Object.entries(params)) {\n    if (value === undefined || value === null) continue;\n    url.searchParams.delete(key);\n    if (Array.isArray(value)) {\n      for (const item of value) url.searchParams.append(key, String(item));\n    } else {\n      url.searchParams.set(key, String(value));\n    }\n  }\n  return url.toString();\n}\n"}'::jsonb),
  ('api-fetch-404', array['b']::text[], '{"en":"fetch only rejects on network failure, CORS blocks or abort. Any HTTP response, including 404 and 500, resolves. Check `response.ok` (status 200–299) and throw yourself if needed.","uk":"fetch відхиляється лише при збої мережі, блокуванні CORS або скасуванні. Будь-яка HTTP-відповідь, включно з 404 і 500, вирішується. Перевіряйте `response.ok` (статус 200–299) і за потреби кидайте помилку самі."}'::jsonb, null::jsonb),
  ('api-localstorage-types', array['b']::text[], '{"en":"localStorage stores strings, so `1` becomes `\"1\"`. `getItem` returns `\"1\"`, and `\"1\" + 2` concatenates to `\"12\"`. Store JSON and parse it back (or use `Number(...)`).","uk":"localStorage зберігає рядки, тож `1` стає `\"1\"`. `getItem` повертає `\"1\"`, а `\"1\" + 2` конкатенується в `\"12\"`. Зберігайте JSON і розбирайте його назад (або використайте `Number(...)`)."}'::jsonb, null::jsonb),
  ('api-abort-stale', array['a']::text[], '{"en":"Responses can arrive out of order. Aborting the previous request (or ignoring responses whose query is no longer current) guarantees only the latest result is applied, and debouncing reduces the number of requests.","uk":"Відповіді можуть приходити в довільному порядку. Скасування попереднього запиту (або ігнорування відповідей, чий запит уже неактуальний) гарантує, що застосовується лише останній результат, а debounce зменшує кількість запитів."}'::jsonb, null::jsonb),
  ('api-intersection-observer', array['a']::text[], '{"en":"IntersectionObserver computes visibility off the main thread''s hot path and calls back only when thresholds are crossed. Scroll handlers with layout reads run on every scroll event and can cause jank. For images, native `loading=\"lazy\"` also works.","uk":"IntersectionObserver обчислює видимість поза гарячим шляхом головного потоку й викликає колбек лише при перетині порогів. Обробники scroll з читанням геометрії виконуються на кожну подію прокрутки й можуть спричиняти ривки. Для зображень також працює нативний `loading=\"lazy\"`."}'::jsonb, null::jsonb),
  ('api-token-storage', array['c']::text[], '{"en":"Injected scripts can read anything JavaScript can read: localStorage, sessionStorage and variables. An `HttpOnly` cookie is sent by the browser but is invisible to scripts, `Secure` limits it to HTTPS, and `SameSite` mitigates CSRF. XSS can still make requests, so prevent XSS too.","uk":"Впроваджені скрипти можуть прочитати все, до чого має доступ JavaScript: localStorage, sessionStorage і змінні. Cookie з `HttpOnly` браузер надсилає, але скрипти його не бачать, `Secure` обмежує його HTTPS, а `SameSite` пом''якшує CSRF. XSS усе одно може робити запити, тож запобігайте й самій XSS."}'::jsonb, null::jsonb),
  ('api-storage-with-ttl', null::text[], '{"en":"Wrap every value in an envelope `{ v, e }` with an optional expiry timestamp and store it as JSON, which preserves types and falsy values. `get` checks the expiry against the injected clock and deletes stale entries. `try/catch` guards both parsing and quota errors. Injecting `storage` and `now` makes the module easy to test.","uk":"Загортайте кожне значення в конверт `{ v, e }` з необов''язковою позначкою часу завершення й зберігайте як JSON, що зберігає типи й хибні значення. `get` порівнює термін дії з підставленим годинником і видаляє застарілі записи. `try/catch` захищає і розбір, і помилки переповнення. Підстановка `storage` і `now` робить модуль легким для тестування."}'::jsonb, '{"/src/store.ts":"type Options = { prefix: string; storage?: Storage; now?: () => number };\ntype Entry = { v: unknown; e: number | null };\n\nexport function createStore({ prefix, storage = localStorage, now = Date.now }: Options) {\n  const k = (key: string) => prefix + key;\n\n  return {\n    set(key: string, value: unknown, ttlMs?: number): boolean {\n      const entry: Entry = { v: value, e: ttlMs == null ? null : now() + ttlMs };\n      try {\n        storage.setItem(k(key), JSON.stringify(entry));\n        return true;\n      } catch {\n        return false; // quota exceeded or storage unavailable\n      }\n    },\n    get<T>(key: string): T | undefined {\n      const raw = storage.getItem(k(key));\n      if (raw == null) return undefined;\n      try {\n        const entry = JSON.parse(raw) as Entry;\n        if (entry.e != null && now() > entry.e) {\n          storage.removeItem(k(key));\n          return undefined;\n        }\n        return entry.v as T;\n      } catch {\n        return undefined;\n      }\n    },\n    remove(key: string): void {\n      storage.removeItem(k(key));\n    },\n  };\n}\n"}'::jsonb),
  ('closure-retained-memory', array['b']::text[], '{"en":"A closure keeps the variables it uses alive for as long as the function itself is reachable. `window` references the listener, the listener references `rows`, so nothing can be collected. Remove the listener when it''s no longer needed (or use an `AbortController` signal), or keep only the data the closure really needs.","uk":"Замикання тримає живими змінні, які використовує, доки сама функція досяжна. `window` посилається на обробник, обробник — на `rows`, тож нічого не може бути зібрано. Знімайте обробник, коли він більше не потрібен (або використовуйте сигнал `AbortController`), чи зберігайте лише ті дані, які замиканню справді потрібні."}'::jsonb, null::jsonb),
  ('closure-let-loop-copy', array['b']::text[], '{"en":"A `let` loop creates a new binding for each iteration, copying the current value into it before the increment runs. The first closure''s binding is incremented to 1 by the `i++` inside the body. The next iteration starts from a copy of 1, the loop''s `i++` makes it 2, the second closure captures that binding, and the body''s `i++` makes it 3. So the closures see 1 and 3.","uk":"Цикл із `let` створює нову прив''язку для кожної ітерації, копіюючи в неї поточне значення перед інкрементом. Прив''язку першого замикання `i++` у тілі збільшує до 1. Наступна ітерація починає з копії 1, `i++` циклу робить її 2, друге замикання захоплює цю прив''язку, а `i++` у тілі робить її 3. Тож замикання бачать 1 і 3."}'::jsonb, null::jsonb),
  ('closure-memoize-async', array['b']::text[], '{"en":"Caching the result only after `await` leaves a window where both calls miss the cache and fire two requests. Caching the promise immediately makes the second caller share the in-flight request. Without deleting rejected promises, a single network error is cached forever. (A `WeakMap` can''t use numbers as keys.)","uk":"Якщо кешувати результат лише після `await`, лишається проміжок, коли обидва виклики не знаходять кеш і роблять два запити. Кешування промісу одразу дає другому викликачу спільний запит у процесі. Без видалення відхилених промісів одна мережева помилка кешується назавжди. (`WeakMap` не може мати числа як ключі.)"}'::jsonb, null::jsonb),
  ('closure-curry', null::text[], '{"en":"Each call returns a new closure over the arguments collected so far. Building a fresh array (`[...args, ...more]`) instead of pushing into a shared one is what keeps partial applications independent. Regular `function` expressions (not arrows) let `this` flow through `apply` to `fn`.","uk":"Кожен виклик повертає нове замикання над уже зібраними аргументами. Створення нового масиву (`[...args, ...more]`) замість додавання до спільного — саме те, що робить часткові застосування незалежними. Звичайні вирази `function` (не стрілкові) дозволяють `this` пройти через `apply` до `fn`."}'::jsonb, '{"/src/curry.js":"export function curry(fn) {\n  return function curried(...args) {\n    if (args.length >= fn.length) return fn.apply(this, args);\n    return function (...more) {\n      return curried.apply(this, [...args, ...more]);\n    };\n  };\n}\n"}'::jsonb),
  ('closure-var-loop', array['b']::text[], '{"en":"`var` creates one function-scoped `i` shared by all callbacks. The timers run after the loop ends, when `i` is 3. With `let`, each iteration gets its own binding and you''d see `0 1 2`.","uk":"`var` створює один `i` в області функції, спільний для всіх колбеків. Таймери спрацьовують після завершення циклу, коли `i` дорівнює 3. З `let` кожна ітерація має власну прив''язку, і виведеться `0 1 2`."}'::jsonb, null::jsonb),
  ('closure-tdz', array['c']::text[], '{"en":"The inner `let name` is hoisted to the top of the function, so it shadows the outer variable for the whole block. Reading it before the declaration line is inside the temporal dead zone, which throws a `ReferenceError`.","uk":"Внутрішній `let name` піднімається на початок функції, тож затіняє зовнішню змінну в усьому блоці. Читання до рядка оголошення потрапляє в temporal dead zone, що кидає `ReferenceError`."}'::jsonb, null::jsonb),
  ('closure-independent-counters', array['b']::text[], '{"en":"Each call to `makeCounter` creates a new `count` variable, captured only by that counter''s function. `a` was called twice (2), `b` once (1).","uk":"Кожен виклик `makeCounter` створює нову змінну `count`, яку захоплює лише функція цього лічильника. `a` викликали двічі (2), `b` один раз (1)."}'::jsonb, null::jsonb),
  ('closure-stale-interval', array['a']::text[], '{"en":"With `[]` dependencies the effect runs once, and its callback keeps reading `count` from that render, so it sets 0 + 1 every second. The updater form reads the latest state without re-creating the interval.","uk":"З залежностями `[]` ефект виконується один раз, і його колбек постійно читає `count` з того рендеру, тож щосекунди встановлює 0 + 1. Форма з функцією-оновлювачем читає актуальний стан без перестворення інтервалу."}'::jsonb, null::jsonb),
  ('closure-memoize-falsy', array['b']::text[], '{"en":"The cached value is 0 (0² = 0), so `if (cache.get(arg))` is false and the function runs again. Testing membership with `has` works for every value, including 0, \"\", false and undefined.","uk":"Закешоване значення дорівнює 0 (0² = 0), тож `if (cache.get(arg))` хибне, і функція виконується знову. Перевірка через `has` працює для будь-якого значення, включно з 0, \"\", false і undefined."}'::jsonb, null::jsonb),
  ('closure-once-and-memoize', null::text[], '{"en":"Both helpers keep private state in a closure. `once` stores a flag and the first result, and uses `fn.apply(this, args)` to forward `this`. `memoize` keeps a Map and checks membership with `has`, so falsy results are cached too.","uk":"Обидві функції зберігають приватний стан у замиканні. `once` зберігає прапорець і перший результат та передає `this` через `fn.apply(this, args)`. `memoize` тримає Map і перевіряє наявність через `has`, тож хибні результати теж кешуються."}'::jsonb, '{"/src/fn.js":"export function once(fn) {\n  let called = false;\n  let result;\n  return function (...args) {\n    if (!called) {\n      called = true;\n      result = fn.apply(this, args);\n    }\n    return result;\n  };\n}\n\nexport function memoize(fn) {\n  const cache = new Map();\n  return function (arg, ...rest) {\n    if (!cache.has(arg)) cache.set(arg, fn.call(this, arg, ...rest));\n    return cache.get(arg);\n  };\n}\n"}'::jsonb),
  ('css-margin-collapse', array['b']::text[], '{"en":"Adjacent vertical margins of block boxes in normal flow collapse into one margin equal to the larger of them, so the gap is 30px, not 50px. Margins don''t collapse inside flex or grid containers, which is one reason many layouts use `gap` instead.","uk":"Сусідні вертикальні відступи блокових елементів у звичайному потоці схлопуються в один, що дорівнює більшому з них, тож проміжок — 30px, а не 50px. Усередині flex- і grid-контейнерів відступи не схлопуються — одна з причин, чому багато макетів використовують `gap`."}'::jsonb, null::jsonb),
  ('css-where-specificity', array['b']::text[], '{"en":"`:where()` always contributes zero specificity, so `:where(#nav) a` is (0,0,1), the same as `a`. With equal specificity the later rule wins: blue. `:is(#nav) a` would take the specificity of its most specific argument, (1,0,1), and win. Libraries use `:where()` so their defaults are easy to override.","uk":"`:where()` завжди додає нульову специфічність, тож `:where(#nav) a` має (0,0,1), як і `a`. За рівної специфічності перемагає пізніше правило: синій. `:is(#nav) a` отримав би специфічність найспецифічнішого аргументу, (1,0,1), і переміг би. Бібліотеки використовують `:where()`, щоб їхні типові стилі легко перевизначались."}'::jsonb, null::jsonb),
  ('css-fixed-containing-block', array['b']::text[], '{"en":"An ancestor with `transform`, `filter`, `perspective`, `contain: paint` or `will-change: transform` becomes the containing block for `position: fixed` descendants, so they are positioned and clipped relative to it instead of the viewport. Render modals in a portal at the end of `<body>`, or use `<dialog>`, which goes into the top layer.","uk":"Предок із `transform`, `filter`, `perspective`, `contain: paint` або `will-change: transform` стає контейнувальним блоком для нащадків із `position: fixed`, тож вони позиціонуються й обрізаються відносно нього, а не вікна. Рендерте модальні вікна через портал у кінці `<body>` або використовуйте `<dialog>`, що потрапляє у верхній шар."}'::jsonb, null::jsonb),
  ('css-specificity', array['b']::text[], '{"en":"Specificities: `#nav a` = (1,0,1), `.menu .link` = (0,2,0), `a.link` = (0,1,1), `nav a` = (0,0,2). The id selector wins regardless of source order.","uk":"Специфічності: `#nav a` = (1,0,1), `.menu .link` = (0,2,0), `a.link` = (0,1,1), `nav a` = (0,0,2). Селектор з id перемагає незалежно від порядку в коді."}'::jsonb, null::jsonb),
  ('css-box-sizing', array['c']::text[], '{"en":"content-box: width covers only the content, so 200 + 2×20 padding + 2×2 border = 244px. With `border-box` it would be exactly 200px.","uk":"content-box: ширина охоплює лише вміст, тож 200 + 2×20 padding + 2×2 рамки = 244px. З `border-box` було б рівно 200px."}'::jsonb, null::jsonb),
  ('css-flex-vs-grid', array['a']::text[], '{"en":"Grid is two-dimensional: columns stay aligned across rows, and `auto-fill` + `minmax` creates as many columns as fit. Wrapped flex items size row by row, so the last row''s items stretch or misalign. Tables are for tabular data.","uk":"Grid двовимірний: колонки вирівнюються між рядками, а `auto-fill` + `minmax` створює стільки колонок, скільки вміщується. Flex-елементи з перенесенням розраховуються рядок за рядком, тож в останньому рядку вони розтягуються або зсуваються. Таблиці призначені для табличних даних."}'::jsonb, null::jsonb),
  ('css-stacking-context', array['a']::text[], '{"en":"z-index values are compared only within the same stacking context. If an ancestor with `transform`, `opacity < 1`, `filter` or a positioned z-index forms a context below the header, nothing inside can rise above it. Render modals in a portal at the end of `<body>`.","uk":"Значення z-index порівнюються лише в межах одного контексту накладання. Якщо предок із `transform`, `opacity < 1`, `filter` або позиціюванням із z-index утворює контекст нижче шапки, ніщо всередині не підніметься вище. Рендерте модальні вікна через портал у кінці `<body>`."}'::jsonb, null::jsonb),
  ('css-visually-hidden', array['c']::text[], '{"en":"`display: none` and `visibility: hidden` remove content from the accessibility tree too. The \"visually hidden\" pattern keeps it in the tree while taking no visible space. Zero-height tricks are unreliable across screen readers.","uk":"`display: none` і `visibility: hidden` прибирають вміст і з дерева доступності. Патерн «візуально прихований» залишає його в дереві, не займаючи видимого місця. Трюки з нульовою висотою ненадійні в різних зчитувачах."}'::jsonb, null::jsonb),
  ('css-dashboard-layout', null::text[], '{"en":"Flexbox handles the one-dimensional toolbar (`justify-content` on the main axis, `align-items` on the cross axis). Grid with `repeat(auto-fill, minmax(160px, 1fr))` makes responsive columns. An absolutely positioned badge needs a positioned ancestor (`position: relative` on the card). The visually-hidden pattern clips the label to 1px while keeping it in the accessibility tree.","uk":"Flexbox обробляє одновимірну панель (`justify-content` на головній осі, `align-items` на поперечній). Grid з `repeat(auto-fill, minmax(160px, 1fr))` дає адаптивні колонки. Абсолютно позиціонованому бейджу потрібен позиціонований предок (`position: relative` на картці). Патерн visually-hidden обрізає мітку до 1px, залишаючи її в дереві доступності."}'::jsonb, '{"/styles.css":"* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font-family: system-ui, sans-serif;\n  background: #f7f5ef;\n}\n\n.toolbar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 16px;\n  background: #0b5a43;\n  color: white;\n}\n\n.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));\n  gap: 16px;\n  list-style: none;\n  margin: 0;\n  padding: 16px;\n}\n\n.card {\n  position: relative;\n  background: white;\n  border-radius: 12px;\n  padding: 16px;\n}\n\n.badge {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  background: #c9a227;\n  border-radius: 999px;\n  padding: 2px 8px;\n  font-size: 12px;\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n"}'::jsonb),
  ('ds-map-vs-object', array['a', 'b', 'c']::text[], '{"en":"`Map` accepts any key type, tracks `size`, keeps insertion order (objects reorder integer-like keys) and has no prototype keys to collide with. It is also optimised for frequent additions and deletions. But `JSON.stringify(new Map(...))` gives `{}`; convert with `Object.fromEntries(map)` first.","uk":"`Map` приймає ключі будь-якого типу, відстежує `size`, зберігає порядок вставки (об''єкти переставляють ключі, схожі на цілі числа) і не має ключів прототипу, з якими можна конфліктувати. Також він оптимізований для частих додавань і видалень. Але `JSON.stringify(new Map(...))` дає `{}`; спершу перетворіть через `Object.fromEntries(map)`."}'::jsonb, null::jsonb),
  ('ds-trie-autocomplete', array['c']::text[], '{"en":"A trie walks one node per typed character, so finding the prefix node costs O(prefix length), independent of the number of names, and everything below it is a match. A hash set only answers exact lookups, and a scan is O(n) per keystroke. A sorted array with binary search for the prefix range is a good, more memory-efficient alternative.","uk":"Префіксне дерево проходить по одному вузлу на кожен введений символ, тож пошук вузла префікса коштує O(довжина префікса) незалежно від кількості назв, а все під ним — збіги. Хеш-множина відповідає лише на точні запити, а перебір — O(n) на кожне натискання. Відсортований масив із бінарним пошуком діапазону префікса — хороша й економніша за пам''яттю альтернатива."}'::jsonb, null::jsonb),
  ('ds-union-find', array['b']::text[], '{"en":"Union-find stores a parent pointer per element. `find` follows pointers to the group''s root, and path compression flattens the path as it goes. With union by rank, both `union` and `find` cost amortised O(α(n)), effectively constant. BFS per query is O(V + E), and an adjacency matrix needs O(n²) memory.","uk":"Union-find зберігає вказівник на батька для кожного елемента. `find` іде вказівниками до кореня групи, а стиснення шляхів вирівнює шлях дорогою. З об''єднанням за рангом і `union`, і `find` коштують амортизовано O(α(n)), тобто фактично сталий час. BFS на кожен запит — O(V + E), а матриця суміжності потребує O(n²) пам''яті."}'::jsonb, null::jsonb),
  ('ds-min-heap', null::text[], '{"en":"In an array heap the children of index i are 2i+1 and 2i+2, and its parent is ⌊(i−1)/2⌋. `push` appends and sifts the item up while it is smaller than its parent. `pop` takes the root, moves the last item to the root and sifts it down towards the smaller child. Both touch one root-to-leaf path: O(log n). The starter''s `shift()` was O(n) and didn''t keep heap order at all.","uk":"У купі на масиві діти індексу i — це 2i+1 і 2i+2, а батько — ⌊(i−1)/2⌋. `push` додає в кінець і піднімає елемент, доки він менший за батька. `pop` бере корінь, переносить останній елемент у корінь і опускає його до меншої дитини. Обидві операції проходять один шлях від кореня до листка: O(log n). `shift()` у заготовці був O(n) і взагалі не підтримував порядок купи."}'::jsonb, '{"/src/priority-queue.ts":"export class PriorityQueue<T> {\n  private items: T[] = [];\n\n  constructor(private compare: (a: T, b: T) => number) {}\n\n  get size() {\n    return this.items.length;\n  }\n\n  peek(): T | undefined {\n    return this.items[0];\n  }\n\n  push(item: T) {\n    const items = this.items;\n    items.push(item);\n    let i = items.length - 1;\n    while (i > 0) {\n      const parent = (i - 1) >> 1;\n      if (this.compare(items[i], items[parent]) >= 0) break;\n      [items[i], items[parent]] = [items[parent], items[i]];\n      i = parent;\n    }\n  }\n\n  pop(): T | undefined {\n    const items = this.items;\n    if (items.length === 0) return undefined;\n    const top = items[0];\n    const last = items.pop()!;\n    if (items.length > 0) {\n      items[0] = last;\n      let i = 0;\n      for (;;) {\n        const left = 2 * i + 1;\n        const right = left + 1;\n        let smallest = i;\n        if (left < items.length && this.compare(items[left], items[smallest]) < 0) smallest = left;\n        if (right < items.length && this.compare(items[right], items[smallest]) < 0) smallest = right;\n        if (smallest === i) break;\n        [items[i], items[smallest]] = [items[smallest], items[i]];\n        i = smallest;\n      }\n    }\n    return top;\n  }\n}\n"}'::jsonb),
  ('ds-stack-brackets', array['b']::text[], '{"en":"The most recently opened bracket must close first, which is last-in, first-out. Push openers and pop on each closer, checking that it matches. The string is balanced if the stack ends empty.","uk":"Остання відкрита дужка має закритися першою, тобто «останнім прийшов, першим вийшов». Додавайте відкривальні дужки в стек і на кожній закривальній знімайте вершину, перевіряючи відповідність. Рядок збалансований, якщо стек у кінці порожній."}'::jsonb, null::jsonb),
  ('ds-queue-shift', array['a']::text[], '{"en":"Removing the first element moves every other element down one index. Keep a `head` index into the array (`queue[head++]`), or use a linked list or ring buffer for O(1) dequeues.","uk":"Видалення першого елемента зсуває всі інші на одну позицію. Тримайте індекс `head` у масиві (`queue[head++]`) або використайте зв''язний список чи кільцевий буфер для вилучення за O(1)."}'::jsonb, null::jsonb),
  ('ds-two-sum-map', array['a']::text[], '{"en":"For each `x`, check whether `target - x` is already in the Map (O(1) average). If not, store `x → index`. One pass gives O(n) time and O(n) space. Sorting plus two pointers is O(n log n) and loses the original indexes.","uk":"Для кожного `x` перевірте, чи є `target - x` у Map (у середньому O(1)). Якщо немає, збережіть `x → індекс`. Один прохід дає O(n) часу й O(n) пам''яті. Сортування з двома вказівниками коштує O(n log n) і втрачає початкові індекси."}'::jsonb, null::jsonb),
  ('ds-heap-topk', array['b']::text[], '{"en":"A min-heap of the current top 100 exposes the smallest of them at the root. Each new score is compared with the root and replaces it if larger, at O(log k) per item. Memory stays O(k).","uk":"Min-купа поточних топ-100 тримає найменшу з них у корені. Кожну нову оцінку порівнюють із коренем і замінюють його, якщо вона більша, за O(log k) на елемент. Пам''ять залишається O(k)."}'::jsonb, null::jsonb),
  ('ds-bst-degenerate', array['c']::text[], '{"en":"Every new value is larger than the last, so each node only has a right child: the tree degenerates into a linked list of height n. Self-balancing trees (AVL, red-black) keep the height O(log n).","uk":"Кожне нове значення більше за попереднє, тож у кожного вузла лише правий нащадок: дерево вироджується в зв''язний список висоти n. Самобалансовані дерева (AVL, червоно-чорні) тримають висоту O(log n)."}'::jsonb, null::jsonb),
  ('ds-lru-cache', null::text[], '{"en":"A Map iterates in insertion order. Deleting and re-inserting a key moves it to the end (most recent), and the first key is always the least recently used. Every operation is O(1). The classic language-agnostic version pairs a hash map with a doubly linked list.","uk":"Map ітерується в порядку вставки. Видалення й повторна вставка ключа переносить його в кінець (найсвіжіший), а перший ключ завжди найдавніше використаний. Кожна операція працює за O(1). Класична незалежна від мови версія поєднує хеш-таблицю з двозв''язним списком."}'::jsonb, '{"/src/lru.ts":"export class LRUCache<K, V> {\n  private map = new Map<K, V>();\n\n  constructor(private capacity: number) {}\n\n  get(key: K): V | undefined {\n    if (!this.map.has(key)) return undefined;\n    const value = this.map.get(key)!;\n    // Re-insert to move the key to the \"most recent\" end.\n    this.map.delete(key);\n    this.map.set(key, value);\n    return value;\n  }\n\n  set(key: K, value: V): void {\n    if (this.map.has(key)) this.map.delete(key);\n    this.map.set(key, value);\n    if (this.map.size > this.capacity) {\n      const oldest = this.map.keys().next().value as K;\n      this.map.delete(oldest);\n    }\n  }\n\n  get size(): number {\n    return this.map.size;\n  }\n}\n"}'::jsonb),
  ('dom-capture-order', array['b']::text[], '{"en":"An event travels down from the window to the target (capture phase), runs the target''s listeners, then travels back up (bubble phase). Listeners registered with `true` or `{ capture: true }` run on the way down, so the parent''s capture listener fires first even though it was added second.","uk":"Подія спускається від window до цілі (фаза перехоплення), виконує обробники цілі, а потім піднімається назад (фаза спливання). Обробники, зареєстровані з `true` або `{ capture: true }`, спрацьовують на шляху вниз, тож обробник перехоплення батька виконується першим, хоч доданий другим."}'::jsonb, null::jsonb),
  ('dom-focus-delegation', array['a', 'b']::text[], '{"en":"`focus` and `blur` don''t bubble, so a listener on an ancestor never sees them in the bubble phase. `focusin`/`focusout` are the bubbling equivalents, and a capture-phase listener sees every event on its way down to the target. Making the form focusable only lets the form itself take focus.","uk":"`focus` і `blur` не спливають, тож обробник на предку не бачить їх у фазі спливання. `focusin`/`focusout` — їхні аналоги, що спливають, а обробник у фазі перехоплення бачить кожну подію на шляху до цілі. Якщо зробити форму фокусованою, фокус зможе отримати лише сама форма."}'::jsonb, null::jsonb),
  ('dom-composed-events', array['b']::text[], '{"en":"`bubbles` lets an event travel up the tree, but `composed` decides whether it crosses the shadow boundary into the light DOM. Without it, propagation ends at the shadow root. Composed events are retargeted, so outside listeners see the host element as `event.target`, keeping the internals encapsulated.","uk":"`bubbles` дозволяє події підніматися деревом, а `composed` визначає, чи перетне вона межу тіньового дерева у світлий DOM. Без нього поширення закінчується на shadow root. Composed-події перенацілюються, тож зовнішні обробники бачать хост-елемент як `event.target`, а внутрішня будова лишається інкапсульованою."}'::jsonb, null::jsonb),
  ('dom-click-outside', null::text[], '{"en":"Listen on the document and use `element.contains(target)`, which is true for the element itself and every descendant. Registering `pointerdown` in the capture phase means a `stopPropagation()` elsewhere on the page can''t hide the click. The cleanup must pass the same function references (and the same `capture` flag) to `removeEventListener`.","uk":"Слухайте на document і використовуйте `element.contains(target)` — це true для самого елемента й усіх нащадків. Реєстрація `pointerdown` у фазі перехоплення означає, що `stopPropagation()` деінде на сторінці не приховає клік. Очищення має передати в `removeEventListener` ті самі посилання на функції (і той самий прапорець `capture`)."}'::jsonb, '{"/src/click-outside.ts":"export function onClickOutside(element: HTMLElement, handler: (event: Event) => void): () => void {\n  const onPointerDown = (event: Event) => {\n    if (!element.contains(event.target as Node)) handler(event);\n  };\n  const onKeyDown = (event: KeyboardEvent) => {\n    if (event.key === \"Escape\") handler(event);\n  };\n\n  document.addEventListener(\"pointerdown\", onPointerDown, true);\n  document.addEventListener(\"keydown\", onKeyDown);\n\n  return () => {\n    document.removeEventListener(\"pointerdown\", onPointerDown, true);\n    document.removeEventListener(\"keydown\", onKeyDown);\n  };\n}\n"}'::jsonb),
  ('dom-target-vs-current', array['c']::text[], '{"en":"`currentTarget` is the element whose listener is currently running (the `<ul>`). `target` is where the event originated, the `<span>`. Delegation uses `target.closest(...)` to find the item.","uk":"`currentTarget` є елементом, чий обробник зараз виконується (`<ul>`). `target` є місцем, звідки подія почалася, тобто `<span>`. Делегування використовує `target.closest(...)`, щоб знайти елемент."}'::jsonb, null::jsonb),
  ('dom-prevent-vs-stop', array['a']::text[], '{"en":"The two are independent: `preventDefault` cancels the browser''s default action (navigation for a submit), and `stopPropagation` prevents other listeners up the tree from receiving the event.","uk":"Це незалежні речі: `preventDefault` скасовує дію браузера за замовчуванням (для submit це навігація), а `stopPropagation` не дає іншим обробникам вище за деревом отримати подію."}'::jsonb, null::jsonb),
  ('dom-delegation-benefits', array['a', 'b']::text[], '{"en":"One listener on the container covers current and future children, which saves memory and setup work. It relies on bubbling, so non-bubbling events need their bubbling variants (`focusin`) or capture. XSS is unrelated.","uk":"Один обробник на контейнері охоплює поточних і майбутніх нащадків, що заощаджує пам''ять і роботу з налаштування. Він покладається на спливання, тож для подій, що не спливають, потрібні їхні спливні варіанти (`focusin`) або фаза занурення. До XSS це стосунку не має."}'::jsonb, null::jsonb),
  ('dom-textcontent-xss', array['a']::text[], '{"en":"`innerHTML` doesn''t execute `<script>` tags, but event-handler attributes like `onerror` do run. Insert untrusted text with `textContent`, or sanitise rich HTML (e.g. DOMPurify) and add a Content-Security-Policy.","uk":"`innerHTML` не виконує теги `<script>`, але атрибути-обробники на кшталт `onerror` спрацьовують. Вставляйте неперевірений текст через `textContent` або санітизуйте форматований HTML (наприклад, DOMPurify) і додайте Content-Security-Policy."}'::jsonb, null::jsonb),
  ('dom-layout-thrashing', array['a']::text[], '{"en":"Interleaving writes (`style.width = …`) and layout reads (`offsetWidth`) forces the browser to recalculate layout on every iteration. Batch the reads, then the writes (or use `requestAnimationFrame`) so the layout is computed once.","uk":"Чергування записів (`style.width = …`) і читань геометрії (`offsetWidth`) змушує браузер перераховувати розкладку на кожній ітерації. Згрупуйте спершу читання, потім записи (або використайте `requestAnimationFrame`), щоб розкладка обчислювалася один раз."}'::jsonb, null::jsonb),
  ('dom-event-delegation', null::text[], '{"en":"Listen once on the root and let events bubble up to it. `event.target.closest(selector)` finds the nearest matching ancestor, so clicks on inner icons count. `root.contains(match)` rejects matches that live above the root. Keep a reference to the listener so the returned function can remove it.","uk":"Слухайте один раз на корені й дозвольте подіям спливати до нього. `event.target.closest(selector)` знаходить найближчого предка, що відповідає селектору, тож кліки по внутрішніх іконках теж рахуються. `root.contains(match)` відкидає збіги, що лежать вище за корінь. Збережіть посилання на обробник, щоб повернена функція могла його зняти."}'::jsonb, '{"/src/delegate.js":"export function delegate(root, selector, type, handler) {\n  function listener(event) {\n    const start = event.target instanceof Element ? event.target : event.target.parentElement;\n    const match = start && start.closest(selector);\n    if (match && root.contains(match)) handler(event, match);\n  }\n  root.addEventListener(type, listener);\n  return () => root.removeEventListener(type, listener);\n}\n"}'::jsonb),
  ('esm-named-default', array['b']::text[], '{"en":"A default export is imported without braces, under any name you choose. Named exports are imported inside braces with their exact names (or renamed with `as`). One statement can do both: `import sum, { PI } from ...`.","uk":"Типовий експорт імпортується без фігурних дужок під будь-яким ім''ям. Іменовані експорти імпортуються у фігурних дужках з точними іменами (або перейменовуються через `as`). Одна інструкція може робити обидва: `import sum, { PI } from ...`."}'::jsonb, null::jsonb),
  ('esm-top-level-await', array['b']::text[], '{"en":"A module with top-level `await` becomes asynchronous: modules that import it (directly or indirectly) wait for it to finish evaluating before they run. The thread isn''t blocked, and unrelated parts of the graph can still evaluate. Use it for real initialisation, because a slow await delays everything that depends on the module.","uk":"Модуль з `await` на верхньому рівні стає асинхронним: модулі, що його імпортують (прямо чи опосередковано), чекають завершення його виконання. Потік не блокується, і незалежні частини графа все одно можуть виконуватися. Використовуйте це для справжньої ініціалізації, бо повільний await затримує все, що залежить від модуля."}'::jsonb, null::jsonb),
  ('esm-cjs-interop', array['b']::text[], '{"en":"When ESM imports CommonJS, the default import is always `module.exports`. Named imports only exist for names that Node''s static analysis (cjs-module-lexer) can detect, such as `exports.parse = ...`. Exports built in a loop aren''t detectable, so linking fails with \"does not provide an export named ''parse''\". Use the default import and destructure it.","uk":"Коли ESM імпортує CommonJS, типовий імпорт — це завжди `module.exports`. Іменовані імпорти існують лише для імен, які може виявити статичний аналіз Node (cjs-module-lexer), наприклад `exports.parse = ...`. Експорти, створені в циклі, не виявляються, тож зв''язування падає з \"does not provide an export named ''parse''\". Використайте типовий імпорт і деструктуризуйте його."}'::jsonb, null::jsonb),
  ('esm-evaluation-order', null::text[], '{"en":"This is a depth-first post-order traversal. Marking a module as visited **before** walking its imports both deduplicates shared dependencies and breaks cycles: when `b` imports `a` while `a` is still loading, `a` is skipped, which is exactly why a circular import can see uninitialised bindings. `hasOwnProperty` avoids treating names like `toString` as modules.","uk":"Це обхід у глибину з post-order. Позначення модуля відвіданим **до** обходу його імпортів і прибирає дублі спільних залежностей, і розриває цикли: коли `b` імпортує `a`, поки `a` ще завантажується, `a` пропускається — саме тому циклічний імпорт може бачити неініціалізовані прив''язки. `hasOwnProperty` не дає сприйняти імена на кшталт `toString` як модулі."}'::jsonb, '{"/src/order.ts":"export type ModuleGraph = Record<string, string[]>;\n\nexport function evaluationOrder(graph: ModuleGraph, entry: string): string[] {\n  const order: string[] = [];\n  const visited = new Set<string>();\n\n  const visit = (name: string) => {\n    if (visited.has(name)) return; // already evaluated, or in progress (a cycle)\n    if (!Object.prototype.hasOwnProperty.call(graph, name)) {\n      throw new Error(\"Cannot find module ''\" + name + \"''\");\n    }\n    visited.add(name);\n    for (const dependency of graph[name]) visit(dependency);\n    order.push(name);\n  };\n\n  visit(entry);\n  return order;\n}\n"}'::jsonb),
  ('esm-live-binding', array['b']::text[], '{"en":"ES module imports are live, read-only bindings to the exporting module''s variables. After `inc()` runs, `count` in `main.js` reflects the new value, 1. CommonJS would have copied the value 0.","uk":"Імпорти ES-модулів є живими прив''язками лише для читання до змінних модуля, що експортує. Після `inc()` змінна `count` у `main.js` показує нове значення 1. CommonJS скопіював би значення 0."}'::jsonb, null::jsonb),
  ('esm-tree-shaking', array['a']::text[], '{"en":"`import`/`export` must be top-level with literal specifiers, so a bundler can build the dependency graph statically and drop unused exports. `require` can be called conditionally with computed paths, and `module.exports` can be mutated at runtime.","uk":"`import`/`export` мають бути на верхньому рівні з літеральними шляхами, тож збирач може статично побудувати граф залежностей і прибрати невикористані експорти. `require` можна викликати умовно з обчисленими шляхами, а `module.exports` змінювати під час виконання."}'::jsonb, null::jsonb),
  ('esm-evaluate-once', array['a']::text[], '{"en":"A module is evaluated once per module graph (realm), and every importer receives the same module instance. That''s why module-level state behaves like a singleton.","uk":"Модуль виконується один раз на граф модулів (realm), і кожен імпортер отримує той самий екземпляр. Тому стан на рівні модуля поводиться як синглтон."}'::jsonb, null::jsonb),
  ('esm-dynamic-import', array['a']::text[], '{"en":"`import()` returns a promise for the module namespace object (`{ default, ...named }`). Bundlers turn it into a separate chunk, so heavy features like editors or charts load only when needed.","uk":"`import()` повертає проміс об''єкта простору імен модуля (`{ default, ...named }`). Збирачі виносять його в окремий чанк, тож важкі функції, як-от редактори чи графіки, завантажуються лише за потреби."}'::jsonb, null::jsonb),
  ('esm-circular', array['b']::text[], '{"en":"Dependencies are evaluated before the importer, so `b.js` runs while `a.js` is still uninitialised. Reading a `let`/`const` export at that moment throws. Fix it by moving the shared value into a third module, or by only accessing it lazily inside functions.","uk":"Залежності виконуються раніше за імпортера, тож `b.js` працює, поки `a.js` ще не ініціалізовано. Читання експорту `let`/`const` у цей момент кидає помилку. Виправлення: винесіть спільне значення в третій модуль або звертайтеся до нього ліниво, лише всередині функцій."}'::jsonb, null::jsonb),
  ('git-fetch-pull', array['a']::text[], '{"en":"`git fetch` is always safe: it updates `origin/*` without touching your working tree, so you can inspect incoming changes (`git log HEAD..origin/main`) first. `git pull` = fetch + integrate. Setting `pull.rebase` or `pull.ff=only` controls how it integrates.","uk":"`git fetch` завжди безпечний: він оновлює `origin/*`, не чіпаючи робочої копії, тож можна спершу переглянути вхідні зміни (`git log HEAD..origin/main`). `git pull` = fetch + інтеграція. Налаштування `pull.rebase` або `pull.ff=only` визначають, як саме відбувається інтеграція."}'::jsonb, null::jsonb),
  ('git-revert-merge', array['a']::text[], '{"en":"A merge commit has two parents, so Git needs to know which side is the mainline to keep. Parent 1 is the branch you merged into (`main`), so `-m 1` undoes the feature''s changes. Rewriting shared history with a force push is the wrong tool on `main`. Note: to re-merge the feature later, you must first revert the revert.","uk":"Коміт злиття має двох батьків, тож Git має знати, яку сторону вважати основною. Батько 1 — гілка, в яку зливали (`main`), тож `-m 1` скасовує зміни функції. Переписування спільної історії примусовим push — неправильний інструмент для `main`. Зауважте: щоб потім злити функцію знову, спершу потрібно скасувати цей revert."}'::jsonb, null::jsonb),
  ('git-ours-theirs-rebase', array['b']::text[], '{"en":"During a rebase, Git replays your commits on top of `main`, so \"ours\" is the branch being built (`main` plus already replayed commits) and \"theirs\" is the commit being replayed, which is yours. That is the reverse of a merge. Then `git add config.ts` and `git rebase --continue`.","uk":"Під час rebase Git перевідтворює ваші коміти поверх `main`, тож «ours» — гілка, що будується (`main` плюс уже перенесені коміти), а «theirs» — коміт, що переноситься, тобто ваш. Це протилежно до merge. Далі `git add config.ts` і `git rebase --continue`."}'::jsonb, null::jsonb),
  ('git-semver-bump', null::text[], '{"en":"Parse each header with one regex: type, optional `(scope)`, optional `!`, then `: `. Requiring `: ` right after the type is what rejects look-alikes such as `feature:` or `fixup!`. Each commit maps to a bump level, and the release takes the maximum. A multiline regex (`/m`) finds `BREAKING CHANGE:` at the start of any body line. Real tools such as semantic-release also treat 0.x versions specially.","uk":"Розбирайте кожен заголовок одним регулярним виразом: тип, необов''язкова `(область)`, необов''язковий `!`, потім `: `. Вимога `: ` одразу після типу відсікає схожі варіанти, як-от `feature:` чи `fixup!`. Кожен коміт дає рівень підвищення, а реліз бере максимум. Багаторядковий вираз (`/m`) знаходить `BREAKING CHANGE:` на початку будь-якого рядка тіла. Справжні інструменти, як-от semantic-release, ще й особливо обробляють версії 0.x."}'::jsonb, '{"/src/semver.ts":"type Bump = 0 | 1 | 2 | 3; // none, patch, minor, major\n\nconst HEADER = /^(\\w+)(\\([^)]*\\))?(!)?: /;\n\nfunction bumpFor(message: string): Bump {\n  const header = HEADER.exec(message);\n  if (!header) return 0;\n  const type = header[1].toLowerCase();\n  if (header[3] || /^BREAKING[ -]CHANGE: /m.test(message)) return 3;\n  if (type === \"feat\") return 2;\n  if (type === \"fix\" || type === \"perf\") return 1;\n  return 0;\n}\n\nexport function nextVersion(current: string, commits: string[]): string {\n  const [major, minor, patch] = current.split(\".\").map(Number);\n  const bump = commits.reduce<Bump>((max, message) => Math.max(max, bumpFor(message)) as Bump, 0);\n  if (bump === 3) return major + 1 + \".0.0\";\n  if (bump === 2) return major + \".\" + (minor + 1) + \".0\";\n  if (bump === 1) return major + \".\" + minor + \".\" + (patch + 1);\n  return current;\n}\n"}'::jsonb),
  ('git-staging', array['a']::text[], '{"en":"The staging area decides what goes into the next commit. `git add <file>` (or `git add -p` for parts of a file) stages exactly what you want. `commit -a` would include every tracked modified file.","uk":"Індекс визначає, що потрапить у наступний коміт. `git add <file>` (або `git add -p` для частин файлу) додає саме те, що потрібно. `commit -a` включив би всі змінені відстежувані файли."}'::jsonb, null::jsonb),
  ('git-revert-vs-reset', array['a']::text[], '{"en":"`revert` adds a new commit that inverts the changes, so history stays intact and teammates aren''t affected. Resetting and force-pushing rewrites shared history and breaks everyone who already pulled.","uk":"`revert` додає новий коміт, що скасовує зміни, тож історія лишається цілою й колеги не постраждають. Reset з force-push переписує спільну історію й ламає роботу всім, хто вже отримав зміни."}'::jsonb, null::jsonb),
  ('git-rebase-golden-rule', array['a']::text[], '{"en":"Rebasing creates new commits. Anyone who based work on the old ones now has a history Git sees as different, which leads to duplicated commits and painful merges. Rebase private branches; merge or revert on shared ones.","uk":"Rebase створює нові коміти. Кожен, хто працював на основі старих, тепер має історію, яку Git вважає іншою, що призводить до дубльованих комітів і болісних злиттів. Робіть rebase приватних гілок, а для спільних використовуйте merge чи revert."}'::jsonb, null::jsonb),
  ('git-reflog', array['a']::text[], '{"en":"The reflog records where HEAD and branches pointed recently, including commits no longer reachable from any branch. They stay recoverable until garbage collection (typically 30+ days).","uk":"Reflog записує, куди нещодавно вказували HEAD і гілки, включно з комітами, недосяжними з жодної гілки. Їх можна відновити, доки їх не прибере збирач сміття (зазвичай 30+ днів)."}'::jsonb, null::jsonb),
  ('git-bisect', array['a']::text[], '{"en":"Bisect is a binary search over history: each good/bad answer halves the range, so log₂(1000) ≈ 10 steps. With `git bisect run <test-script>` it can be fully automated.","uk":"Bisect є бінарним пошуком по історії: кожна відповідь good/bad вдвічі звужує діапазон, тож потрібно log₂(1000) ≈ 10 кроків. З `git bisect run <test-script>` процес можна повністю автоматизувати."}'::jsonb, null::jsonb),
  ('html-dialog-modal', array['a', 'b', 'c']::text[], '{"en":"`showModal()` opens the dialog in the top layer with a `::backdrop`, makes everything else inert and closes it on Escape (firing `cancel`). `show()` opens a non-modal dialog in normal flow, without any of that. Forms with `method=\"dialog\"` close the dialog on submit; nothing is submitted automatically.","uk":"`showModal()` відкриває діалог у верхньому шарі з `::backdrop`, робить решту сторінки інертною й закриває його за Escape (з подією `cancel`). `show()` відкриває немодальний діалог у звичайному потоці без усього цього. Форми з `method=\"dialog\"` закривають діалог під час надсилання; нічого не надсилається автоматично."}'::jsonb, null::jsonb),
  ('html-preload-lcp', array['a']::text[], '{"en":"An `<img>` in the HTML is found by the preload scanner immediately, and `fetchpriority=\"high\"` moves it ahead of other images. If it must stay a background, `rel=\"preload\"` makes it discoverable early. Lazy-loading the LCP image delays it further, `prefetch` is a low-priority hint for future navigations, and moving the CSS causes unstyled flashes.","uk":"`<img>` у HTML одразу знаходить сканер попереднього завантаження, а `fetchpriority=\"high\"` ставить його попереду інших зображень. Якщо зображення мусить лишатися фоном, `rel=\"preload\"` робить його видимим браузеру рано. Ліниве завантаження LCP-зображення ще більше його затримає, `prefetch` — низькопріоритетна підказка для майбутніх переходів, а перенесення CSS спричинить спалахи нестилізованого вмісту."}'::jsonb, null::jsonb),
  ('html-srcset-sizes', array['c']::text[], '{"en":"`sizes` says the image is 50vw wide on this viewport, so the slot is 500 CSS px. At DPR 2 the browser needs about 1000 device pixels and picks the smallest candidate that covers it: `hero-960.jpg` is too small, so it takes `hero-1440.jpg`. Without `sizes`, the browser would assume 100vw and need 2000 pixels. Only one file is downloaded.","uk":"`sizes` каже, що на цьому вікні зображення має ширину 50vw, тобто слот — 500 CSS-пікселів. За DPR 2 браузеру потрібно близько 1000 фізичних пікселів, і він бере найменшого кандидата, що їх покриває: `hero-960.jpg` замалий, тож буде `hero-1440.jpg`. Без `sizes` браузер вважав би ширину 100vw і потребував би 2000 пікселів. Завантажується лише один файл."}'::jsonb, null::jsonb),
  ('html-button-vs-div', array['a']::text[], '{"en":"A native button gets keyboard focus, the `button` role for assistive technology, Enter/Space activation and form submission semantics for free. A div needs `role`, `tabindex` and key handlers to approximate that.","uk":"Нативна кнопка безкоштовно отримує фокус клавіатури, роль `button` для допоміжних технологій, активацію Enter/Space і семантику надсилання форми. Div потребує `role`, `tabindex` і обробників клавіш, щоб лише наблизитися до цього."}'::jsonb, null::jsonb),
  ('html-defer-async', array['b']::text[], '{"en":"Deferred scripts download in parallel and execute after parsing, in document order. Async scripts run as soon as each one arrives, so their order isn''t guaranteed. Plain scripts block the parser.","uk":"Відкладені (defer) скрипти завантажуються паралельно й виконуються після розбору в порядку документа. Async-скрипти виконуються, щойно кожен надійде, тож порядок не гарантовано. Звичайні скрипти блокують розбір."}'::jsonb, null::jsonb),
  ('html-button-default-type', array['a']::text[], '{"en":"Buttons in forms submit by default. Add `type=\"button\"` to buttons that aren''t meant to submit, or call `preventDefault()` in the submit handler.","uk":"Кнопки у формах за замовчуванням надсилають форму. Додайте `type=\"button\"` кнопкам, які не повинні надсилати, або викликайте `preventDefault()` в обробнику submit."}'::jsonb, null::jsonb),
  ('html-label-association', array['a', 'b', 'd']::text[], '{"en":"An explicit `for`/`id` pair, a wrapping label and `aria-label` all name the field. A placeholder is only a fallback hint: it vanishes while typing, often has poor contrast, and shouldn''t replace a label.","uk":"Явна пара `for`/`id`, обгортальна мітка й `aria-label` дають полю ім''я. Placeholder є лише запасною підказкою: зникає під час введення, часто має слабкий контраст і не повинен замінювати мітку."}'::jsonb, null::jsonb),
  ('html-heading-order', array['b']::text[], '{"en":"Heading levels describe the outline, not the visual size. Skipping from h1 to h4 confuses screen-reader navigation and the document outline. Use the correct level and adjust its look with CSS.","uk":"Рівні заголовків описують структуру, а не візуальний розмір. Перехід від h1 одразу до h4 плутає навігацію зчитувачів екрана й структуру документа. Використайте правильний рівень і змініть вигляд через CSS."}'::jsonb, null::jsonb),
  ('html-semantic-signup-form', null::text[], '{"en":"Semantic elements carry their meaning to browsers and assistive technology: `<main>` and `<h1>` structure the page, each `<label>` names its control, the input types and `autocomplete` give the right keyboard and autofill, `required`/`minlength` add native validation, and a `<button type=\"submit\">` submits the form with the keyboard too.","uk":"Семантичні елементи передають своє значення браузерам і допоміжним технологіям: `<main>` і `<h1>` структурують сторінку, кожен `<label>` дає ім''я своєму полю, типи полів і `autocomplete` дають правильну клавіатуру й автозаповнення, `required`/`minlength` додають нативну валідацію, а `<button type=\"submit\">` надсилає форму й з клавіатури."}'::jsonb, '{"/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Sign up</title>\n</head>\n<body>\n  <main>\n    <h1>Create your account</h1>\n    <form>\n      <label for=\"email\">Email</label>\n      <input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required />\n\n      <label for=\"password\">Password</label>\n      <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" required />\n\n      <label>\n        <input type=\"checkbox\" name=\"terms\" required />\n        I accept the terms\n      </label>\n\n      <button type=\"submit\">Create account</button>\n    </form>\n  </main>\n\n  <script src=\"index.js\"></script>\n</body>\n</html>\n"}'::jsonb),
  ('http-put-patch', array['b']::text[], '{"en":"`PUT` replaces the whole resource with the body, so sending only the email would, strictly, clear the other fields. `PATCH` applies a partial update. Changing state with `GET` is never acceptable: it must be safe, and it gets cached, prefetched and logged.","uk":"`PUT` замінює весь ресурс тілом запиту, тож надсилання лише email, строго кажучи, очистило б інші поля. `PATCH` застосовує часткове оновлення. Змінювати стан через `GET` неприпустимо: він має бути безпечним, а ще його кешують, завантажують наперед і логують."}'::jsonb, null::jsonb),
  ('http-if-match', array['b']::text[], '{"en":"This is optimistic concurrency control. The `ETag` identifies the version the editor loaded. With `If-Match`, the server applies the write only if the current version still matches, and otherwise returns 412, so the client can reload and merge. `If-None-Match: *` is the opposite guard: create only if the resource doesn''t exist yet.","uk":"Це оптимістичне керування конкурентністю. `ETag` ідентифікує версію, яку завантажив редактор. З `If-Match` сервер застосовує запис, лише якщо поточна версія досі збігається, інакше повертає 412, і клієнт може перезавантажити й об''єднати зміни. `If-None-Match: *` — протилежна умова: створити, лише якщо ресурсу ще немає."}'::jsonb, null::jsonb),
  ('http-idempotency-key', array['b']::text[], '{"en":"The client generates a unique key per logical operation and sends it with every attempt. The server records the key with the outcome (atomically, handling concurrent duplicates) and replays the stored response for repeats, turning a non-idempotent POST into a safely retryable one. This is how payment APIs such as Stripe work. Waiting doesn''t remove the ambiguity.","uk":"Клієнт генерує унікальний ключ на кожну логічну операцію й надсилає його з кожною спробою. Сервер записує ключ разом із результатом (атомарно, з обробкою одночасних дублів) і повертає збережену відповідь на повтори — так неідемпотентний POST стає безпечним для повторів. Так працюють платіжні API, як-от Stripe. Очікування не прибирає невизначеності."}'::jsonb, null::jsonb),
  ('http-paginate-link', null::text[], '{"en":"Split the header into comma-separated links, then pull the URL out of `<...>` and the `rel` value from its parameter (a `rel` can list several space-separated names). `fetchAll` is a loop, not recursion: request, check `ok`, append, then read the next URL from the response. The page cap protects against a server that links a page to itself. Splitting on commas is fine for typical APIs; a URL that contains a comma needs a real parser.","uk":"Розбийте заголовок на посилання, розділені комами, потім витягніть URL з `<...>` і значення `rel` з його параметра (`rel` може містити кілька імен через пробіл). `fetchAll` — цикл, а не рекурсія: запит, перевірка `ok`, додавання, потім читання наступного URL з відповіді. Обмеження кількості сторінок захищає від сервера, що посилається сторінкою на саму себе. Розбиття за комами підходить для типових API; URL із комою потребує справжнього парсера."}'::jsonb, '{"/src/paginate.ts":"export type PageResponse = {\n  ok: boolean;\n  status: number;\n  headers: { get(name: string): string | null };\n  json(): Promise<unknown>;\n};\nexport type Fetcher = (url: string) => Promise<PageResponse>;\n\nconst MAX_PAGES = 50;\n\nexport function parseLink(header: string | null): Record<string, string> {\n  const links: Record<string, string> = {};\n  if (!header) return links;\n  for (const part of header.split(\",\")) {\n    const url = /<([^>]*)>/.exec(part)?.[1];\n    const rel = /rel=\"?([^\";]+)\"?/.exec(part)?.[1];\n    if (url && rel) for (const name of rel.trim().split(/\\s+/)) links[name] = url;\n  }\n  return links;\n}\n\nexport async function fetchAll<T>(url: string, fetcher: Fetcher): Promise<T[]> {\n  const items: T[] = [];\n  let next: string | undefined = url;\n  for (let page = 0; next && page < MAX_PAGES; page++) {\n    const response = await fetcher(next);\n    if (!response.ok) throw new Error(\"HTTP \" + response.status + \" for \" + next);\n    items.push(...((await response.json()) as T[]));\n    next = parseLink(response.headers.get(\"link\")).next;\n  }\n  return items;\n}\n"}'::jsonb),
  ('http-401-vs-403', array['b']::text[], '{"en":"401 means \"we don''t know who you are\": missing or invalid credentials. 403 means \"we know who you are, but you''re not allowed\". Some APIs return 404 to hide that a resource exists at all, a deliberate trade-off.","uk":"401 означає «ми не знаємо, хто ви»: облікові дані відсутні чи недійсні. 403 означає «ми знаємо, хто ви, але вам не дозволено». Деякі API повертають 404, щоб приховати саме існування ресурсу; це свідомий компроміс."}'::jsonb, null::jsonb),
  ('http-idempotent-methods', array['a', 'c', 'd']::text[], '{"en":"Repeating GET, PUT (replace with the same representation) or DELETE leaves the server in the same state as doing it once, so clients can retry them safely. POST may create a new resource each time; use an idempotency key for safe retries.","uk":"Повторення GET, PUT (заміна тим самим представленням) чи DELETE залишає сервер у тому ж стані, що й одне виконання, тож клієнти можуть безпечно повторювати їх. POST може щоразу створювати новий ресурс; для безпечних повторів використовуйте ключ ідемпотентності."}'::jsonb, null::jsonb),
  ('http-cors-preflight', array['a']::text[], '{"en":"PUT and a JSON content type are not \"simple\", so the browser asks first with `OPTIONS` (including `Access-Control-Request-Method`/`-Headers`). The server must reply with matching `Access-Control-Allow-*` headers. The fix belongs on the server, not in the client.","uk":"PUT і тип вмісту JSON не є «простими», тож браузер спершу питає дозволу через `OPTIONS` (з `Access-Control-Request-Method`/`-Headers`). Сервер має відповісти відповідними заголовками `Access-Control-Allow-*`. Виправлення робиться на сервері, а не в клієнті."}'::jsonb, null::jsonb),
  ('http-cache-control', array['b']::text[], '{"en":"A content hash means the URL changes whenever the file changes, so the response can be cached for a year without revalidation. The HTML that references it should use `no-cache` so users pick up new hashes.","uk":"Хеш вмісту означає, що URL змінюється разом із файлом, тож відповідь можна кешувати рік без перевірки. HTML, що на неї посилається, має використовувати `no-cache`, щоб користувачі отримували нові хеші."}'::jsonb, null::jsonb),
  ('http-rest-create', array['b']::text[], '{"en":"201 signals that a resource was created, and `Location` tells the client its URL. Returning the representation saves an extra GET.","uk":"201 повідомляє, що ресурс створено, а `Location` повідомляє клієнту його URL. Повернення представлення в тілі заощаджує додатковий GET."}'::jsonb, null::jsonb),
  ('js-nan-includes', array['a']::text[], '{"en":"`includes` uses the SameValueZero algorithm, which treats `NaN` as equal to itself. `indexOf` uses strict equality (`===`), and `NaN === NaN` is `false`, so it returns -1. Use `Number.isNaN` or `includes` when you need to find `NaN`.","uk":"`includes` використовує алгоритм SameValueZero, для якого `NaN` дорівнює собі. `indexOf` використовує строгу рівність (`===`), а `NaN === NaN` дає `false`, тож повертає -1. Щоб знайти `NaN`, використовуйте `Number.isNaN` або `includes`."}'::jsonb, null::jsonb),
  ('js-key-order', array['b']::text[], '{"en":"Own property order is specified: integer-like keys first in ascending numeric order, then string keys in insertion order, then symbols (which `Object.keys` skips). Don''t rely on insertion order for numeric-looking keys; use a `Map` if order matters.","uk":"Порядок власних властивостей визначено: спершу ключі-цілі числа за зростанням, потім рядкові ключі в порядку вставки, потім символи (їх `Object.keys` пропускає). Не покладайтеся на порядок вставки для ключів, схожих на числа; якщо порядок важливий, використовуйте `Map`."}'::jsonb, null::jsonb),
  ('js-structured-clone', array['a', 'c', 'd']::text[], '{"en":"`structuredClone` uses the structured clone algorithm (the same as `postMessage`). It handles `Map`, `Set`, `Date`, typed arrays and cycles, but throws a `DataCloneError` for functions and DOM nodes. Class instances come back as plain objects: the prototype, getters and methods are lost.","uk":"`structuredClone` використовує алгоритм структурного клонування (той самий, що й `postMessage`). Він обробляє `Map`, `Set`, `Date`, типізовані масиви й цикли, але кидає `DataCloneError` для функцій і DOM-вузлів. Екземпляри класів повертаються як звичайні об''єкти: прототип, гетери й методи втрачаються."}'::jsonb, null::jsonb),
  ('js-deep-equal', null::text[], '{"en":"Handle the cheap cases first: `Object.is` covers identical references, primitives and `NaN`. Anything that isn''t a non-null object is then unequal. Special-case `Date`, then make sure both sides are arrays or both are objects before comparing items or keys. Checking key counts plus `hasOwnProperty` catches `{ a: undefined }` vs `{}`. The recursion depth equals the nesting depth of the data.","uk":"Спершу прості випадки: `Object.is` покриває однакові посилання, примітиви й `NaN`. Усе, що не є ненульовим об''єктом, далі нерівне. Окремо обробіть `Date`, потім переконайтеся, що обидві сторони — масиви або обидві — об''єкти, і лише тоді порівнюйте елементи чи ключі. Перевірка кількості ключів разом із `hasOwnProperty` ловить `{ a: undefined }` проти `{}`. Глибина рекурсії дорівнює глибині вкладеності даних."}'::jsonb, '{"/src/deep-equal.ts":"type Dict = Record<string, unknown>;\n\nexport function deepEqual(a: unknown, b: unknown): boolean {\n  if (Object.is(a, b)) return true;\n  if (typeof a !== \"object\" || typeof b !== \"object\" || a === null || b === null) return false;\n\n  if (a instanceof Date || b instanceof Date) {\n    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();\n  }\n\n  if (Array.isArray(a) !== Array.isArray(b)) return false;\n  if (Array.isArray(a) && Array.isArray(b)) {\n    return a.length === b.length && a.every((item, i) => deepEqual(item, b[i]));\n  }\n\n  const keysA = Object.keys(a);\n  const keysB = Object.keys(b);\n  if (keysA.length !== keysB.length) return false;\n  return keysA.every((key) => Object.prototype.hasOwnProperty.call(b, key) && deepEqual((a as Dict)[key], (b as Dict)[key]));\n}\n"}'::jsonb),
  ('js-typeof-null', array['b']::text[], '{"en":"A long-standing bug from the first JavaScript implementation that can''t be fixed without breaking the web. Check for null with `value === null`.","uk":"Давня помилка першої реалізації JavaScript, яку не можна виправити, не зламавши веб. Перевіряйте null через `value === null`."}'::jsonb, null::jsonb),
  ('js-reference-equality', array['b']::text[], '{"en":"Objects are compared by reference. `a` and `b` are two distinct objects, so `a === b` is false. `c` points at the same object as `a`, so `a === c` is true.","uk":"Об''єкти порівнюються за посиланням. `a` і `b` є двома різними об''єктами, тому `a === b` дає false. `c` вказує на той самий об''єкт, що й `a`, тому `a === c` дає true."}'::jsonb, null::jsonb),
  ('js-falsy-values', array['a', 'd', 'e']::text[], '{"en":"The falsy values are `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` and `NaN`. Non-empty strings like `\"0\"` and every object, including empty arrays, are truthy.","uk":"Хибні значення: `false`, `0`, `-0`, `0n`, `\"\"`, `null`, `undefined` і `NaN`. Непорожні рядки на кшталт `\"0\"` і будь-які об''єкти, зокрема порожні масиви, є істинними."}'::jsonb, null::jsonb),
  ('js-this-callback', array['b']::text[], '{"en":"`this` depends on the call site. `setTimeout` calls the function on its own, not as `counter.inc()`, so `this` is `undefined` in strict mode, and reading `this.count` throws. Fix it with `setTimeout(() => counter.inc())` or `counter.inc.bind(counter)`.","uk":"`this` залежить від місця виклику. `setTimeout` викликає функцію окремо, а не як `counter.inc()`, тож у strict mode `this` дорівнює `undefined`, і читання `this.count` кидає помилку. Виправлення: `setTimeout(() => counter.inc())` або `counter.inc.bind(counter)`."}'::jsonb, null::jsonb),
  ('js-prototype-lookup', array['a']::text[], '{"en":"`delete child.kind` removes the own property, so the lookup continues up the prototype chain and finds `kind` on `base`. Deleting never touches the prototype.","uk":"`delete child.kind` видаляє власну властивість, тож пошук продовжується ланцюжком прототипів і знаходить `kind` у `base`. Видалення ніколи не зачіпає прототип."}'::jsonb, null::jsonb),
  ('js-group-by', null::text[], '{"en":"One pass with an accumulator object: compute the key, create the bucket on first use (`??=`), push the item. It runs in O(n). Modern runtimes also ship `Object.groupBy`, which has the same semantics.","uk":"Один прохід з об''єктом-акумулятором: обчислюємо ключ, створюємо «кошик» при першому використанні (`??=`) і додаємо елемент. Складність O(n). Сучасні середовища також мають `Object.groupBy` з такою самою семантикою."}'::jsonb, '{"/src/groupBy.js":"export function groupBy(items, keyFn) {\n  const result = {};\n  for (const item of items) {\n    const key = keyFn(item);\n    (result[key] ??= []).push(item);\n  }\n  return result;\n}\n"}'::jsonb),
  ('node-type-module', array['b']::text[], '{"en":"`\"type\": \"module\"` makes `.js` files in the package ES modules; `.cjs` stays CommonJS and `.mjs` is always ESM. In ESM, use `import`, `import.meta.dirname` (or `fileURLToPath(import.meta.url)`) and `createRequire` when you really need `require`.","uk":"`\"type\": \"module\"` робить файли `.js` у пакеті ES-модулями; `.cjs` лишається CommonJS, а `.mjs` — завжди ESM. В ESM використовуйте `import`, `import.meta.dirname` (або `fileURLToPath(import.meta.url)`) і `createRequire`, коли `require` справді потрібен."}'::jsonb, null::jsonb),
  ('node-backpressure', array['b']::text[], '{"en":"`write()` returns `false` when the writable''s buffer is full. A correct producer pauses until `drain`. Ignoring it buffers everything in memory. `pipeline` handles the pause/resume for you, propagates errors and destroys every stream on failure, which a manual `.pipe()` chain doesn''t.","uk":"`write()` повертає `false`, коли буфер записуваного потоку заповнений. Коректний виробник призупиняється до події `drain`. Якщо це ігнорувати, усе буферизується в пам''яті. `pipeline` сам призупиняє й відновлює, передає помилки й знищує всі потоки в разі збою — чого ручний ланцюжок `.pipe()` не робить."}'::jsonb, null::jsonb),
  ('node-immediate-vs-timeout', array['b']::text[], '{"en":"The callback runs in the poll phase. The event loop moves on to the check phase (where `setImmediate` callbacks run) before it wraps around to the timers phase, so `immediate` always comes first. At the top level of the main module, the order of these two is not deterministic, because it depends on whether 1 ms has passed when the loop starts.","uk":"Колбек виконується у фазі poll. Цикл подій переходить до фази check (де виконуються колбеки `setImmediate`) раніше, ніж повертається до фази timers, тож `immediate` завжди перший. На верхньому рівні головного модуля порядок цих двох не детермінований, бо залежить від того, чи минула 1 мс на старті циклу."}'::jsonb, null::jsonb),
  ('node-promisify', null::text[], '{"en":"Wrap the call in `new Promise`: its executor already turns synchronous throws into rejections, and the error-first callback maps to `reject`/`resolve`. A regular `function` (not an arrow) receives the caller''s `this`, which `fn.call(this, ...)` forwards. Today you''d usually import `promisify` from `node:util` or use the `node:fs/promises` APIs directly.","uk":"Обгорніть виклик у `new Promise`: його виконавець уже перетворює синхронні винятки на відхилення, а колбек з помилкою першим аргументом зіставляється з `reject`/`resolve`. Звичайна `function` (не стрілкова) отримує `this` викликача, який `fn.call(this, ...)` передає далі. Сьогодні зазвичай імпортують `promisify` з `node:util` або одразу використовують API `node:fs/promises`."}'::jsonb, '{"/src/promisify.js":"export function promisify(fn) {\n  return function (...args) {\n    return new Promise((resolve, reject) => {\n      const callback = (err, value) => (err ? reject(err) : resolve(value));\n      fn.call(this, ...args, callback);\n    });\n  };\n}\n"}'::jsonb),
  ('node-blocking', array['a']::text[], '{"en":"JavaScript callbacks run on one thread, so a long synchronous computation stalls every other request and timer. Move CPU work to worker threads, another service or a job queue.","uk":"Колбеки JavaScript виконуються в одному потоці, тож довге синхронне обчислення зупиняє всі інші запити й таймери. Виносьте CPU-роботу у worker threads, інший сервіс або чергу задач."}'::jsonb, null::jsonb),
  ('node-microtask-order', array['a']::text[], '{"en":"After the current operation completes, Node drains the `process.nextTick` queue first, then the promise microtask queue, and only then moves on to timers and `setImmediate` (whose relative order in the main module can vary).","uk":"Після завершення поточної операції Node спершу вичерпує чергу `process.nextTick`, потім чергу мікрозадач промісів, і лише тоді переходить до таймерів і `setImmediate` (їхній взаємний порядок у головному модулі може відрізнятися)."}'::jsonb, null::jsonb),
  ('node-streams', array['a']::text[], '{"en":"Streams process chunks with constant memory, and `pipeline` handles backpressure and error propagation. Reading the whole file would exceed memory, and synchronous zlib would block the event loop.","uk":"Потоки обробляють частини даних зі сталим обсягом пам''яті, а `pipeline` обробляє зворотний тиск і передає помилки. Читання всього файлу перевищило б пам''ять, а синхронний zlib заблокував би цикл подій."}'::jsonb, null::jsonb),
  ('node-unhandled-rejection', array['a']::text[], '{"en":"Since Node 15 the default `--unhandled-rejections=throw` mode turns an unhandled rejection into an uncaught exception, which crashes the process. Always `await` inside `try/catch` or attach `.catch`.","uk":"Починаючи з Node 15 типовий режим `--unhandled-rejections=throw` перетворює необроблене відхилення на неперехоплений виняток, що завершує процес. Завжди використовуйте `await` усередині `try/catch` або додавайте `.catch`."}'::jsonb, null::jsonb),
  ('node-scaling-cores', array['a']::text[], '{"en":"Each Node process runs JavaScript on one core, so you scale horizontally with multiple processes. Keep them stateless (sessions and caches in Redis or a database) so any instance can serve any request. The libuv thread pool size only affects certain I/O and crypto work.","uk":"Кожен процес Node виконує JavaScript на одному ядрі, тож масштабуються горизонтально, кількома процесами. Тримайте їх без стану (сесії й кеші в Redis чи базі даних), щоб будь-який екземпляр міг обслужити будь-який запит. Розмір пулу потоків libuv впливає лише на певні операції вводу-виводу й криптографії."}'::jsonb, null::jsonb),
  ('react-and-zero', array['b']::text[], '{"en":"`unread && <Badge />` evaluates to `0` when `unread` is 0. React skips `false`, `null` and `undefined`, but numbers are valid children, so a literal 0 appears on the page. Use a real boolean: `unread > 0 && <Badge />` or a ternary.","uk":"`unread && <Badge />` дає `0`, коли `unread` дорівнює 0. React пропускає `false`, `null` і `undefined`, але числа — коректні дочірні елементи, тож на сторінці з''являється 0. Використовуйте справжнє булеве значення: `unread > 0 && <Badge />` або тернарний оператор."}'::jsonb, null::jsonb),
  ('react-nested-component', array['b']::text[], '{"en":"React compares element types by reference. Declaring `Field` inside `Parent` creates a new function on every render, so React sees a different component type, destroys the old subtree with its state and DOM, and mounts a fresh one. Move component definitions to module level and pass data through props.","uk":"React порівнює типи елементів за посиланням. Оголошення `Field` усередині `Parent` створює нову функцію при кожному рендері, тож React бачить інший тип компонента, знищує старе піддерево разом зі станом і DOM та монтує нове. Виносьте оголошення компонентів на рівень модуля й передавайте дані через props."}'::jsonb, null::jsonb),
  ('react-deferred-value', array['a']::text[], '{"en":"`useDeferredValue` lets React render the urgent update (the input) first and re-render the expensive list with the new value in an interruptible background render. It only helps if `<Results>` is memoized, so the urgent render can skip it while the deferred value is unchanged. `useCallback` doesn''t reduce the work, an effect adds an extra render, and `flushSync` forces the slow render to happen synchronously.","uk":"`useDeferredValue` дозволяє React спершу відрендерити термінове оновлення (поле), а дорогий список перемалювати з новим значенням у фоновому рендері, який можна перервати. Це працює лише тоді, коли `<Results>` мемоїзовано, щоб терміновий рендер пропускав його, поки відкладене значення не змінилося. `useCallback` не зменшує роботу, ефект додає зайвий рендер, а `flushSync` змушує повільний рендер виконатися синхронно."}'::jsonb, null::jsonb),
  ('react-state-snapshot', array['b']::text[], '{"en":"Both `setCount(count + 1)` calls read the same snapshot (`0`) and queue `1`. The updater function then receives the latest queued value (`1`) and returns `2`. Use updater functions when the next state depends on the previous one.","uk":"Обидва виклики `setCount(count + 1)` читають той самий знімок (`0`) і ставлять у чергу `1`. Функція-оновлювач отримує останнє значення в черзі (`1`) і повертає `2`. Використовуйте оновлювачі, коли новий стан залежить від попереднього."}'::jsonb, null::jsonb),
  ('react-keys-index', array['b']::text[], '{"en":"Keys identify items across renders. After an insertion at the top, every index points at a different item, so React keeps the old component instances (with their state and uncontrolled input values) under the wrong data. Use a stable unique ID.","uk":"Ключі ідентифікують елементи між рендерами. Після вставки згори кожен індекс вказує на інший елемент, тож React зберігає старі екземпляри компонентів (з їхнім станом і значеннями некерованих полів) під хибними даними. Використовуйте стабільний унікальний ID."}'::jsonb, null::jsonb),
  ('react-effect-cleanup', array['a', 'b']::text[], '{"en":"Cleanup runs before the next execution of the effect (when a dependency changed) and once on unmount. In development, Strict Mode also runs an extra mount→cleanup→mount cycle to surface missing cleanups.","uk":"Очищення виконується перед наступним запуском ефекту (коли змінилася залежність) і один раз при демонтуванні. У розробці Strict Mode також робить додатковий цикл mount→cleanup→mount, щоб виявити відсутні очищення."}'::jsonb, null::jsonb),
  ('react-derived-state', array['a']::text[], '{"en":"`visible` is derived from props/state, so storing it in state creates a second source of truth and an extra render (render → effect → setState → render). Compute it during render instead.","uk":"`visible` є похідним від пропсів/стану, тож зберігання його в стані створює друге джерело правди й зайвий рендер (render → effect → setState → render). Обчислюйте його під час рендеру."}'::jsonb, null::jsonb),
  ('react-memo-callback', array['a']::text[], '{"en":"`memo` compares props shallowly. An inline arrow function creates a new identity every render, so the comparison fails. `useCallback` keeps the same function between renders while its dependencies are unchanged.","uk":"`memo` порівнює пропси поверхнево. Вбудована стрілкова функція щоразу створює нову ідентичність, тож порівняння не проходить. `useCallback` зберігає ту саму функцію між рендерами, поки залежності не змінилися."}'::jsonb, null::jsonb),
  ('react-searchable-list', null::text[], '{"en":"Keep only `query` in state and derive `visible` during render. A `<label htmlFor>` connected to the input''s `id` gives it an accessible name, which is also how the tests find it. Render the empty state conditionally.","uk":"Зберігайте у стані лише `query`, а `visible` обчислюйте під час рендеру. `<label htmlFor>`, пов''язаний з `id` поля, дає йому доступне ім''я, за яким його знаходять і тести. Порожній стан рендерте умовно."}'::jsonb, '{"/App.tsx":"import { useState } from \"react\";\n\nexport const FRUITS = [\"Apple\", \"Apricot\", \"Banana\", \"Cherry\", \"Grape\", \"Mango\"];\n\nexport default function App() {\n  const [query, setQuery] = useState(\"\");\n  const q = query.trim().toLowerCase();\n  const visible = FRUITS.filter((f) => f.toLowerCase().includes(q));\n\n  return (\n    <main>\n      <h1>Fruits</h1>\n      <label htmlFor=\"search\">Search</label>\n      <input id=\"search\" value={query} onChange={(e) => setQuery(e.target.value)} />\n      <p data-testid=\"count\">\n        {visible.length} of {FRUITS.length}\n      </p>\n      {visible.length ? (\n        <ul>\n          {visible.map((f) => (\n            <li key={f}>{f}</li>\n          ))}\n        </ul>\n      ) : (\n        <p>No results</p>\n      )}\n    </main>\n  );\n}\n"}'::jsonb),
  ('rec-frame-count', array['b']::text[], '{"en":"`factorial(4)` calls `factorial(3)`, then 2, then 1, which hits the base case. Each call waits for the next one, so 4 frames are stacked at the deepest point. Stack depth grows linearly with `n`, which is why very large inputs overflow.","uk":"`factorial(4)` викликає `factorial(3)`, потім 2, потім 1, що досягає базового випадку. Кожен виклик чекає на наступний, тож у найглибшій точці в стеку 4 кадри. Глибина стеку зростає лінійно з `n`, тому дуже великі вхідні дані його переповнюють."}'::jsonb, null::jsonb),
  ('rec-tail-calls', array['b']::text[], '{"en":"ES2015 specifies proper tail calls in strict mode, but V8 (Chrome, Node.js) and Firefox never shipped them; only Safari''s JavaScriptCore does. Each call still uses a stack frame, so a million calls overflow. Rewrite deep recursion as a loop, use an explicit stack, or use a trampoline.","uk":"ES2015 визначає оптимізацію хвостових викликів у строгому режимі, але V8 (Chrome, Node.js) і Firefox її так і не впровадили; лише JavaScriptCore у Safari. Кожен виклик досі займає кадр стеку, тож мільйон викликів переповнює стек. Перепишіть глибоку рекурсію циклом, використайте явний стек або трамплін."}'::jsonb, null::jsonb),
  ('rec-trampoline', array['b']::text[], '{"en":"Instead of recursing, each step returns a function describing the next step. The `while` loop calls these thunks one after another, so only one frame is on the stack at a time and depth no longer depends on `n`. The cost is an allocation per step, and results that are themselves functions need a different marker.","uk":"Замість рекурсії кожен крок повертає функцію, що описує наступний крок. Цикл `while` викликає ці thunk-и по черзі, тож у стеку одночасно лише один кадр, і глибина не залежить від `n`. Ціна — одна алокація на крок, а результатам, що самі є функціями, потрібен інший маркер."}'::jsonb, null::jsonb),
  ('rec-unique-permutations', null::text[], '{"en":"Backtracking fills one position per recursion level: mark an unused item, recurse, then undo the choice. A `Set` of values already tried **at this level** prunes duplicate branches before they are explored, so equal values never start two identical subtrees. There are n!/(k₁!·k₂!·…) results, each copied in O(n).","uk":"Пошук із поверненням заповнює одну позицію на кожному рівні рекурсії: позначити невикористаний елемент, рекурсивно продовжити, потім скасувати вибір. `Set` значень, уже випробуваних **на цьому рівні**, відсікає дубльовані гілки ще до їх обходу, тож рівні значення ніколи не породжують два однакові піддерева. Результатів n!/(k₁!·k₂!·…), кожен копіюється за O(n)."}'::jsonb, '{"/src/permutations.ts":"export function permutations<T>(items: T[]): T[][] {\n  const result: T[][] = [];\n  const used = new Array<boolean>(items.length).fill(false);\n  const current: T[] = [];\n\n  const build = () => {\n    if (current.length === items.length) {\n      result.push([...current]);\n      return;\n    }\n    const triedHere = new Set<T>();\n    for (let i = 0; i < items.length; i++) {\n      if (used[i] || triedHere.has(items[i])) continue;\n      triedHere.add(items[i]);\n      used[i] = true;\n      current.push(items[i]);\n      build();\n      current.pop();\n      used[i] = false;\n    }\n  };\n\n  build();\n  return result;\n}\n"}'::jsonb),
  ('rec-base-case', array['b']::text[], '{"en":"There is no base case, so every call recurses again and the call stack overflows. Add `if (n < 0) return;` before the recursive call.","uk":"Базового випадку немає, тож кожен виклик знову рекурсує, і стек викликів переповнюється. Додайте `if (n < 0) return;` перед рекурсивним викликом."}'::jsonb, null::jsonb),
  ('rec-fib-complexity', array['c']::text[], '{"en":"Each call spawns two more and the same sub-problems are recomputed many times, so the number of calls grows exponentially (≈ φⁿ). Memoisation or a bottom-up loop brings it down to O(n).","uk":"Кожен виклик породжує ще два, а ті самі підзадачі обчислюються багато разів, тож кількість викликів зростає експоненційно (≈ φⁿ). Мемоізація або цикл «знизу вгору» знижує складність до O(n)."}'::jsonb, null::jsonb),
  ('rec-stack-depth', array['a']::text[], '{"en":"Each recursive call consumes a stack frame, and engines cap the depth (typically ~10k). Proper tail calls are in the spec but only Safari ships them, so don''t rely on them. An iterative loop uses constant stack space.","uk":"Кожен рекурсивний виклик займає кадр стеку, а рушії обмежують глибину (зазвичай ~10 тис.). Правильні хвостові виклики є в специфікації, але реалізовані лише в Safari, тож покладатися на них не варто. Ітеративний цикл використовує сталий обсяг стеку."}'::jsonb, null::jsonb),
  ('rec-subsets-count', array['c']::text[], '{"en":"Each item is either in or out of a subset, so there are 2ⁿ subsets: 2²⁰ = 1,048,576. Permutations would be n! (option D), which is astronomically larger.","uk":"Кожен елемент або входить до підмножини, або ні, тож підмножин 2ⁿ: 2²⁰ = 1 048 576. Перестановок було б n! (варіант D), що астрономічно більше."}'::jsonb, null::jsonb),
  ('rec-tree-traversal', array['b']::text[], '{"en":"In a BST every value in the left subtree is smaller and every value in the right subtree is larger. Visiting left, then the node, then right yields sorted output.","uk":"У BST усі значення лівого піддерева менші, а правого більші. Обхід «ліве, вузол, праве» дає відсортований вивід."}'::jsonb, null::jsonb),
  ('rec-flatten-depth', null::text[], '{"en":"Walk the array. When an item is an array and there is depth left, recurse with `depth - 1` and append its result; otherwise append the item as is. The base case is implicit: a call on an array without nested arrays (or with depth 0) just copies its items.","uk":"Пройдіть масив. Якщо елемент є масивом і глибина ще лишилася, рекурсивно викличте функцію з `depth - 1` і додайте її результат; інакше додайте елемент як є. Базовий випадок неявний: виклик на масиві без вкладених масивів (або з глибиною 0) просто копіює елементи."}'::jsonb, '{"/src/flatten.js":"export function flatten(array, depth = Infinity) {\n  const out = [];\n  for (const item of array) {\n    if (Array.isArray(item) && depth > 0) {\n      for (const inner of flatten(item, depth - 1)) out.push(inner);\n    } else {\n      out.push(item);\n    }\n  }\n  return out;\n}\n"}'::jsonb),
  ('rx-vs-promise', array['a']::text[], '{"en":"A Promise represents a single future value and starts its work immediately (eager). A typical (cold) Observable is lazy, runs once per subscriber, can emit zero to many values, and can be torn down with `unsubscribe()`. That makes it a good fit for events, streams and cancellable requests.","uk":"Promise представляє одне майбутнє значення й починає роботу одразу (енергійно). Типовий (холодний) Observable лінивий, виконується окремо для кожного підписника, може випромінити від нуля до багатьох значень і зупиняється через `unsubscribe()`. Тож він добре підходить для подій, потоків і запитів, які можна скасувати."}'::jsonb, null::jsonb),
  ('rx-share-replay', array['b']::text[], '{"en":"`share()` multicasts but doesn''t replay, so late subscribers miss the value. `shareReplay(1)` replays, but with `refCount: false` (the default) it keeps the inner subscription alive forever, a classic leak with long-lived sources. `refCount: true` unsubscribes from the source when the last subscriber leaves. `take(1)` alone doesn''t share anything.","uk":"`share()` робить мультикаст, але не повторює значення, тож пізні підписники його пропускають. `shareReplay(1)` повторює, але з `refCount: false` (типово) тримає внутрішню підписку назавжди — класичний витік із довгоживучими джерелами. `refCount: true` відписується від джерела, коли йде останній підписник. Сам `take(1)` нічого не робить спільним."}'::jsonb, null::jsonb),
  ('rx-switchmap-sync', array['b']::text[], '{"en":"`of(1, 2, 3)` emits all three values synchronously. Each value makes `switchMap` subscribe to a new `timer(0)` and unsubscribe from the previous one before it can fire. Only the last inner timer survives, so the output is `3`. `mergeMap` would emit `1, 2, 3`, and `exhaustMap` would emit only `1`.","uk":"`of(1, 2, 3)` випромінює всі три значення синхронно. Кожне значення змушує `switchMap` підписатися на новий `timer(0)` і відписатися від попереднього, перш ніж той спрацює. Виживає лише останній внутрішній таймер, тож результат — `3`. `mergeMap` випромінив би `1, 2, 3`, а `exhaustMap` — лише `1`."}'::jsonb, null::jsonb),
  ('rx-cold-http', array['b']::text[], '{"en":"HttpClient observables are cold: every subscriber triggers its own request. Share the result with `shareReplay({ bufferSize: 1, refCount: true })`, or subscribe once (e.g. `@if (user$ | async; as user)`).","uk":"Observable з HttpClient холодні: кожен підписник запускає власний запит. Поділіть результат через `shareReplay({ bufferSize: 1, refCount: true })` або підпишіться один раз (наприклад, `@if (user$ | async; as user)`)."}'::jsonb, null::jsonb),
  ('rx-switchmap-search', array['c']::text[], '{"en":"`switchMap` unsubscribes from the previous inner observable when a new value arrives, which cancels the stale request and prevents out-of-order results. `mergeMap` would let old responses overwrite new ones, `concatMap` would queue every keystroke, and `exhaustMap` would ignore new queries.","uk":"`switchMap` відписується від попереднього внутрішнього observable, коли надходить нове значення: це скасовує застарілий запит і запобігає результатам не в тому порядку. `mergeMap` дозволив би старим відповідям перезаписати нові, `concatMap` ставив би в чергу кожне натискання, а `exhaustMap` ігнорував би нові запити."}'::jsonb, null::jsonb),
  ('rx-exhaustmap-submit', array['b']::text[], '{"en":"`exhaustMap` ignores source values while the inner observable is still active, so extra clicks are dropped until the payment completes. `switchMap` would cancel the first request client-side, but the server may already have processed it.","uk":"`exhaustMap` ігнорує значення джерела, поки внутрішній observable ще активний, тож зайві кліки відкидаються до завершення оплати. `switchMap` скасував би перший запит на клієнті, але сервер міг уже його обробити."}'::jsonb, null::jsonb),
  ('rx-behaviorsubject', array['b']::text[], '{"en":"BehaviorSubject requires an initial value, exposes `.value`, and emits the latest value to each new subscriber, which makes it a minimal state container. A plain Subject has no memory, and AsyncSubject emits only the last value on completion.","uk":"BehaviorSubject потребує початкового значення, має `.value` і видає останнє значення кожному новому підписнику, що робить його мінімальним контейнером стану. Звичайний Subject нічого не пам''ятає, а AsyncSubject видає лише останнє значення при завершенні."}'::jsonb, null::jsonb),
  ('rx-catcherror-placement', array['a']::text[], '{"en":"An error terminates the stream it reaches. Here it reaches the outer pipeline, and `catchError` swaps the whole stream for `of([])`, which emits once and completes. Move `catchError` inside `switchMap` (`search(q).pipe(catchError(() => of([])))`) so only that inner request is replaced.","uk":"Помилка завершує потік, до якого доходить. Тут вона доходить до зовнішнього конвеєра, і `catchError` замінює весь потік на `of([])`, що видає одне значення й завершується. Перенесіть `catchError` усередину `switchMap` (`search(q).pipe(catchError(() => of([])))`), щоб замінювався лише той внутрішній запит."}'::jsonb, null::jsonb),
  ('rx-typeahead', null::text[], '{"en":"`map(trim)` → `debounceTime` waits for a pause → `filter` drops short queries → `distinctUntilChanged` skips repeats → `switchMap` unsubscribes from the previous search, which cancels it. `catchError` must sit inside `switchMap`: there it only replaces the failed inner search with `[]`, while the outer stream keeps listening.","uk":"`map(trim)` → `debounceTime` чекає паузи → `filter` відкидає короткі запити → `distinctUntilChanged` пропускає повтори → `switchMap` відписується від попереднього пошуку й тим скасовує його. `catchError` має бути всередині `switchMap`: там він замінює на `[]` лише невдалий внутрішній пошук, а зовнішній потік продовжує слухати."}'::jsonb, '{"/src/typeahead.ts":"import { Observable, of } from \"rxjs\";\nimport { catchError, debounceTime, distinctUntilChanged, filter, map, switchMap } from \"rxjs/operators\";\n\nexport function createTypeahead(\n  query$: Observable<string>,\n  search: (q: string) => Observable<string[]>,\n  debounceMs: number,\n): Observable<string[]> {\n  return query$.pipe(\n    map((q) => q.trim()),\n    debounceTime(debounceMs),\n    filter((q) => q.length >= 2),\n    distinctUntilChanged(),\n    // switchMap cancels the previous inner search; catchError inside keeps the outer stream alive.\n    switchMap((q) => search(q).pipe(catchError(() => of([] as string[])))),\n  );\n}\n"}'::jsonb),
  ('search-bfs-shortest', array['b']::text[], '{"en":"BFS explores cells in order of distance from the start (all cells 1 move away, then 2, …), so the first time it reaches the exit is via a shortest path. DFS finds a path, not necessarily the shortest. With different move costs, use Dijkstra''s algorithm instead.","uk":"BFS обходить клітинки в порядку віддаленості від старту (усі на відстані 1 хід, потім 2, …), тож уперше він досягає виходу найкоротшим шляхом. DFS знаходить якийсь шлях, не обов''язково найкоротший. Якщо ходи мають різну вартість, використовуйте алгоритм Дейкстри."}'::jsonb, null::jsonb),
  ('search-galloping', array['b']::text[], '{"en":"Doubling the probe index takes about log p steps to overshoot the target, and the final range [i/2, i] has size O(p), so the binary search adds another O(log p). Searching up to `MAX_SAFE_INTEGER` costs a constant ~53 steps, but it''s O(log max), not proportional to where the target is, and jump search needs a known n. TimSort uses galloping when merging runs.","uk":"Подвоєння індексу перевірки потребує близько log p кроків, щоб перескочити ціль, а останній діапазон [i/2, i] має розмір O(p), тож бінарний пошук додає ще O(log p). Пошук до `MAX_SAFE_INTEGER` коштує сталі ~53 кроки, але це O(log max), а не пропорційно положенню цілі, а стрибковому пошуку потрібне відоме n. TimSort використовує галопування під час злиття серій."}'::jsonb, null::jsonb),
  ('search-binary-precondition', array['a']::text[], '{"en":"Binary search discards half of the range by comparing with the middle element, which only works if the data is ordered by the key. Duplicates are allowed (use lower/upper bound to handle them), any length works and any comparable type works.","uk":"Бінарний пошук відкидає половину діапазону, порівнюючи з середнім елементом, а це працює лише для впорядкованих за ключем даних. Дублікати допустимі (для них є нижня/верхня межа), довжина може бути будь-якою, тип — будь-який порівнюваний."}'::jsonb, null::jsonb),
  ('search-binary-complexity', array['a']::text[], '{"en":"Each comparison halves the range, so the count is about log₂(1,000,000) ≈ 20. That is the whole point of O(log n).","uk":"Кожне порівняння вдвічі зменшує діапазон, тож потрібно близько log₂(1 000 000) ≈ 20 порівнянь. У цьому вся суть O(log n)."}'::jsonb, null::jsonb),
  ('search-infinite-loop-bug', array['a']::text[], '{"en":"When `hi - lo === 1`, `mid === lo`. If `a[mid] < x`, assigning `lo = mid` leaves the range unchanged forever. Since `a[mid]` is known to be too small, it can be excluded: `lo = mid + 1`. The other options break the half-open invariant or return wrong positions.","uk":"Коли `hi - lo === 1`, то `mid === lo`. Якщо `a[mid] < x`, присвоєння `lo = mid` назавжди залишає діапазон незмінним. Оскільки `a[mid]` точно замалий, його можна виключити: `lo = mid + 1`. Інші варіанти порушують інваріант напіввідкритого діапазону або повертають хибні позиції."}'::jsonb, null::jsonb),
  ('search-many-lookups', array['b']::text[], '{"en":"`includes`/`find` are O(n) each, so 50,000 lookups cost about 5·10⁹ operations. Building a `Set` is O(n) once, and each `has` is O(1) on average. Sorting once plus binary search (O(n log n + m log n)) would also work, but sorting before every lookup is far worse.","uk":"`includes`/`find` коштують O(n) кожен, тож 50 000 пошуків — це близько 5·10⁹ операцій. Побудова `Set` — O(n) один раз, а кожен `has` — у середньому O(1). Одноразове сортування з бінарним пошуком (O(n log n + m log n)) теж підійде, але сортувати перед кожним пошуком — значно гірше."}'::jsonb, null::jsonb),
  ('search-two-pointers', array['a', 'b', 'd']::text[], '{"en":"On sorted input, a sum that is too small means the left element cannot pair with anything to its right except larger values, so it is discarded and the pointer moves right (and symmetrically for the right pointer). That gives O(n) time with constant space. Without ordering the discard argument fails; use a hash map instead.","uk":"На відсортованих даних замала сума означає, що лівий елемент не утворить пари з жодним елементом, тож його відкидаємо й зсуваємо вказівник праворуч (симетрично для правого вказівника). Звідси O(n) часу та константна пам''ять. Без упорядкування аргумент про відкидання не працює, тому для невідсортованих даних беріть хеш-таблицю."}'::jsonb, null::jsonb),
  ('search-on-answer', array['a']::text[], '{"en":"We binary search over capacities between `max(w)` and `sum(w)`. A greedy O(n) check tells whether a capacity fits in D days, and the answer flips from ''no'' to ''yes'' exactly once, which is the monotonic predicate binary search needs. The weights do not need to be sorted.","uk":"Ми шукаємо бінарно серед місткостей від `max(w)` до `sum(w)`. Жадібна перевірка за O(n) показує, чи вкладається місткість у D днів, а відповідь змінюється з «ні» на «так» рівно один раз. Саме такий монотонний предикат потрібен бінарному пошуку. Ваги відсортовувати не потрібно."}'::jsonb, null::jsonb),
  ('search-implement-binary-search', null::text[], '{"en":"Keep the invariant ''if target exists, it is within [lo, hi]''. Compare with the middle element and shrink the range by excluding `mid` on each side. The loop runs at most ⌈log₂(n+1)⌉ times.","uk":"Тримайте інваріант «якщо target існує, він у [lo, hi]». Порівнюйте з середнім елементом і звужуйте діапазон, виключаючи `mid` з відповідного боку. Цикл виконується не більше ⌈log₂(n+1)⌉ разів."}'::jsonb, '{"/src/binarySearch.ts":"export function binarySearch(items: number[], target: number): number {\n  let lo = 0;\n  let hi = items.length - 1;\n  while (lo <= hi) {\n    const mid = lo + ((hi - lo) >> 1);\n    const value = items[mid];\n    if (value === target) return mid;\n    if (value < target) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}\n"}'::jsonb),
  ('search-count-occurrences', null::text[], '{"en":"The first index with value ≥ x and the first index with value ≥ x+1 bracket the run of x. Two lower-bound searches cost O(log n), regardless of how many duplicates there are. (For non-integers, use an ''upper bound'' with `<=` instead of x+1.)","uk":"Перший індекс зі значенням ≥ x і перший індекс зі значенням ≥ x+1 обмежують серію x. Два пошуки нижньої межі коштують O(log n) незалежно від кількості дублікатів. (Для нецілих чисел використайте «верхню межу» з `<=` замість x+1.)"}'::jsonb, '{"/src/count.ts":"function lowerBound(a: number[], x: number) {\n  let lo = 0;\n  let hi = a.length;\n  while (lo < hi) {\n    const mid = (lo + hi) >> 1;\n    if (a[mid] < x) lo = mid + 1;\n    else hi = mid;\n  }\n  return lo;\n}\n\nexport function countOccurrences(sorted: number[], x: number): number {\n  return lowerBound(sorted, x + 1) - lowerBound(sorted, x);\n}\n"}'::jsonb),
  ('sort-n-log-n', array['c']::text[], '{"en":"Merge sort always splits the input in half (log n levels) and merges each level in O(n). Bubble, insertion and selection sort are O(n²) in the worst case, although insertion sort is fast on small or nearly sorted inputs.","uk":"Сортування злиттям завжди ділить дані навпіл (log n рівнів) і зливає кожен рівень за O(n). Сортування бульбашкою, вставками й вибором мають O(n²) у найгіршому випадку, хоча сортування вставками швидке на малих або майже відсортованих даних."}'::jsonb, null::jsonb),
  ('sort-random-shuffle', array['b']::text[], '{"en":"Sorting algorithms assume a consistent comparator (if a < b and b < c, then a < c). A random one breaks that, and the result depends on the engine''s algorithm, which gives a strongly non-uniform distribution. Use Fisher–Yates: walk from the end and swap each element with a random index at or before it, which is O(n) and unbiased.","uk":"Алгоритми сортування розраховують на узгоджений компаратор (якщо a < b і b < c, то a < c). Випадковий порушує це, і результат залежить від алгоритму рушія, що дає дуже нерівномірний розподіл. Використовуйте Фішера–Єйтса: ідіть з кінця й міняйте кожен елемент з випадковим індексом не далі за нього — це O(n) і без упередження."}'::jsonb, null::jsonb),
  ('sort-external', array['b']::text[], '{"en":"External merge sort reads memory-sized chunks, sorts each in RAM and writes sorted runs to disk. A k-way merge then streams all runs at once, using a min-heap of the current head of each run to output records in order. Disk access stays sequential, which is what makes it fast. Timestamps have far too large a range for counting sort.","uk":"Зовнішнє сортування злиттям читає частини розміром із пам''ять, сортує кожну в RAM і записує відсортовані серії на диск. Потім k-шляхове злиття читає всі серії потоково, використовуючи мін-купу з поточних перших елементів серій, щоб виводити записи по порядку. Доступ до диска лишається послідовним — саме це робить підхід швидким. Діапазон міток часу завеликий для сортування підрахунком."}'::jsonb, null::jsonb),
  ('sort-by-keys', null::text[], '{"en":"One comparator walks the keys in priority order and returns the first non-zero comparison, flipping the sign for descending keys. `Array.prototype.sort` is guaranteed stable since ES2019, so returning 0 for full ties keeps the input order. Copying with `[...items]` avoids mutating the caller''s array (or use `toSorted`).","uk":"Один компаратор проходить ключі за пріоритетом і повертає перше ненульове порівняння, змінюючи знак для спадних ключів. `Array.prototype.sort` гарантовано стабільний з ES2019, тож повернення 0 для повних збігів зберігає вхідний порядок. Копія через `[...items]` не дає змінити масив викликача (або використайте `toSorted`)."}'::jsonb, '{"/src/sort-by.ts":"export type SortKey<T> = { key: keyof T; dir?: \"asc\" | \"desc\" };\n\nfunction compareValues(a: unknown, b: unknown): number {\n  if (typeof a === \"number\" && typeof b === \"number\") return a - b;\n  return String(a).localeCompare(String(b));\n}\n\nexport function sortBy<T>(items: T[], keys: SortKey<T>[]): T[] {\n  return [...items].sort((a, b) => {\n    for (const { key, dir = \"asc\" } of keys) {\n      const result = compareValues(a[key], b[key]);\n      if (result !== 0) return dir === \"desc\" ? -result : result;\n    }\n    return 0;\n  });\n}\n"}'::jsonb),
  ('sort-stability', array['a']::text[], '{"en":"Stability is about ties. It lets you sort by a secondary key, then by a primary key, and keep the secondary order inside each primary group. `Array.prototype.sort` has been stable since ES2019.","uk":"Стабільність стосується рівних елементів. Вона дозволяє відсортувати за другорядним ключем, потім за основним і зберегти другорядний порядок усередині кожної групи. `Array.prototype.sort` стабільний з ES2019."}'::jsonb, null::jsonb),
  ('sort-quick-worst', array['a']::text[], '{"en":"On sorted input the first element is the minimum, so each partition peels off only one element and recursion depth becomes n. Random or median-of-three pivots make this practically impossible.","uk":"На відсортованих даних перший елемент є мінімумом, тож кожне розбиття відокремлює лише один елемент, і глибина рекурсії стає n. Випадковий опорний елемент або медіана трьох роблять це практично неможливим."}'::jsonb, null::jsonb),
  ('sort-lower-bound', array['b']::text[], '{"en":"The O(n log n) lower bound applies only to comparison sorts. With a tiny key range, count how many times each score occurs (101 buckets) and write them out in order: linear time.","uk":"Нижня межа O(n log n) стосується лише сортувань порівнянням. Коли діапазон ключів крихітний, порахуйте, скільки разів трапляється кожен бал (101 комірка), і випишіть їх по порядку: лінійний час."}'::jsonb, null::jsonb),
  ('sort-multi-key', array['a']::text[], '{"en":"When ages differ, `a.age - b.age` is non-zero and decides the order. When they''re equal it''s 0 (falsy), so `||` falls through to the name comparison. Comparators must return numbers, not booleans.","uk":"Коли вік різний, `a.age - b.age` ненульове й визначає порядок. Коли однаковий, результат 0 (хибне значення), тож `||` переходить до порівняння імен. Компаратор має повертати числа, а не булеві значення."}'::jsonb, null::jsonb),
  ('sort-merge-memory', array['b']::text[], '{"en":"Heapsort guarantees O(n log n) worst case with O(1) extra memory (in place). Merge sort needs O(n) buffers, quicksort''s worst case is O(n²), and counting sort needs a small key range.","uk":"Пірамідальне сортування гарантує O(n log n) у найгіршому випадку з O(1) додаткової пам''яті (на місці). Злиття потребує буферів O(n), найгірший випадок quicksort дорівнює O(n²), а сортування підрахунком вимагає малого діапазону ключів."}'::jsonb, null::jsonb),
  ('sort-merge-sort', null::text[], '{"en":"Split in half, sort each half recursively, and merge by repeatedly taking the smaller head. Taking from the right half only when it''s *strictly* smaller keeps ties in input order, which makes the sort stable. Depth is log n with O(n) work per level, so O(n log n) total, with O(n) extra memory.","uk":"Розділіть навпіл, рекурсивно відсортуйте кожну половину й злийте, щоразу беручи менший перший елемент. Беріть із правої половини лише коли він *строго* менший: так рівні елементи зберігають вхідний порядок, і сортування стабільне. Глибина log n і O(n) роботи на рівень дають разом O(n log n) з O(n) додаткової пам''яті."}'::jsonb, '{"/src/mergeSort.ts":"export function mergeSort<T>(items: T[], compare: (a: T, b: T) => number): T[] {\n  if (items.length <= 1) return items.slice();\n  const mid = items.length >> 1;\n  const left = mergeSort(items.slice(0, mid), compare);\n  const right = mergeSort(items.slice(mid), compare);\n\n  const out: T[] = [];\n  let i = 0;\n  let j = 0;\n  while (i < left.length && j < right.length) {\n    // Take from the right only if strictly smaller: ties keep left first (stable).\n    if (compare(right[j], left[i]) < 0) out.push(right[j++]);\n    else out.push(left[i++]);\n  }\n  while (i < left.length) out.push(left[i++]);\n  while (j < right.length) out.push(right[j++]);\n  return out;\n}\n"}'::jsonb),
  ('state-context-rerenders', array['a']::text[], '{"en":"`useContext` subscribes to the whole value; a new object means every consumer re-renders. Split rarely and frequently changing data into separate contexts, memoize the provider value, or use a store with selector subscriptions (Zustand, Redux, `useSyncExternalStore`) so components re-render only when their slice changes.","uk":"`useContext` підписується на все значення; новий об''єкт означає перемальовування кожного споживача. Розділіть дані, що змінюються рідко й часто, на окремі контексти, мемоїзуйте значення провайдера або використайте сховище з підписками через селектори (Zustand, Redux, `useSyncExternalStore`), щоб компоненти перемальовувались лише при зміні їхнього зрізу."}'::jsonb, null::jsonb),
  ('state-normalize', array['b']::text[], '{"en":"Normalised state stores each entity once, keyed by id, and references it by id everywhere else, like database tables. Updates touch one place, lookups are O(1), and memoized selectors join the data for the UI. Redux Toolkit''s `createEntityAdapter` and query caches use this pattern.","uk":"Нормалізований стан зберігає кожну сутність один раз за ключем id і посилається на неї за id всюди, як таблиці бази даних. Оновлення торкаються одного місця, пошук — O(1), а мемоїзовані селектори поєднують дані для UI. Цей шаблон використовують `createEntityAdapter` у Redux Toolkit і кеші запитів."}'::jsonb, null::jsonb),
  ('state-optimistic-race', array['b']::text[], '{"en":"Responses can arrive in any order, so tag each mutation (a counter per item) and ignore responses from superseded requests, or cancel them with `AbortController`. On failure, roll back only if the failed request is still the latest. Debouncing makes the race less likely but doesn''t eliminate it. Libraries such as TanStack Query provide `onMutate`/rollback helpers for this.","uk":"Відповіді можуть надходити в будь-якому порядку, тож позначайте кожну мутацію (лічильник для кожного елемента) і ігноруйте відповіді від замінених запитів або скасовуйте їх через `AbortController`. При помилці відкочуйте лише тоді, коли невдалий запит досі останній. Debounce робить гонку менш імовірною, але не усуває її. Бібліотеки на кшталт TanStack Query мають для цього `onMutate` і засоби відкату."}'::jsonb, null::jsonb),
  ('state-create-store', null::text[], '{"en":"Keep listeners in a `Set` and notify from a copy (`[...listeners]`), so unsubscribing during notification can''t skip anyone. Skipping notification when the reducer returns the same object relies on immutable updates, which is why reducers must never mutate. `select` is just a subscriber that remembers the previous selected value and compares with `Object.is`, the same idea behind `useSelector` and `useSyncExternalStore`.","uk":"Тримайте слухачів у `Set` і сповіщайте з копії (`[...listeners]`), щоб відписка під час сповіщення нікого не пропустила. Пропуск сповіщення, коли редюсер повертає той самий об''єкт, спирається на незмінні оновлення — тому редюсери ніколи не мають змінювати стан. `select` — це просто підписник, що пам''ятає попереднє вибране значення й порівнює через `Object.is`; та сама ідея лежить в основі `useSelector` і `useSyncExternalStore`."}'::jsonb, '{"/src/store.ts":"export type Reducer<S, A> = (state: S, action: A) => S;\n\nexport function createStore<S, A>(reducer: Reducer<S, A>, initialState: S) {\n  let state = initialState;\n  const listeners = new Set<(state: S) => void>();\n\n  const subscribe = (listener: (state: S) => void) => {\n    listeners.add(listener);\n    return () => {\n      listeners.delete(listener);\n    };\n  };\n\n  return {\n    getState: () => state,\n    dispatch(action: A) {\n      const next = reducer(state, action);\n      if (Object.is(next, state)) return;\n      state = next;\n      for (const listener of [...listeners]) listener(state);\n    },\n    subscribe,\n    select<T>(selector: (state: S) => T, listener: (value: T) => void) {\n      let current = selector(state);\n      return subscribe((nextState) => {\n        const value = selector(nextState);\n        if (Object.is(value, current)) return;\n        current = value;\n        listener(value);\n      });\n    },\n  };\n}\n"}'::jsonb),
  ('state-derive-not-store', array['a']::text[], '{"en":"Duplicated state needs every update path to keep both values consistent, and sooner or later one forgets. Store the source of truth (`items`) and derive `total` in render or a memoised selector.","uk":"Продубльований стан вимагає, щоб кожен шлях оновлення тримав обидва значення узгодженими, і рано чи пізно якийсь шлях про це забуде. Зберігайте джерело правди (`items`) і обчислюйте `total` під час рендеру чи в мемоізованому селекторі."}'::jsonb, null::jsonb),
  ('state-mutation-bug', array['a']::text[], '{"en":"React''s `useReducer`, Redux and OnPush compare references. Returning the same object tells them nothing changed. Return new objects along the changed path: `{ ...state, todos: state.todos.map(t => t.id === id ? { ...t, done: !t.done } : t) }`.","uk":"`useReducer` у React, Redux і OnPush порівнюють посилання. Повернення того самого об''єкта повідомляє, що нічого не змінилося. Повертайте нові об''єкти вздовж зміненого шляху: `{ ...state, todos: state.todos.map(t => t.id === id ? { ...t, done: !t.done } : t) }`."}'::jsonb, null::jsonb),
  ('state-server-cache', array['a']::text[], '{"en":"Server data is a cache of someone else''s state: it needs deduplication, background refetching, invalidation and retries. Query libraries provide this, and hand-rolled copies in a client store tend to go stale.","uk":"Серверні дані є кешем чужого стану: їм потрібні дедуплікація, фонове оновлення, інвалідація й повторні спроби. Бібліотеки запитів дають це з коробки, а саморобні копії в клієнтському сторі зазвичай застарівають."}'::jsonb, null::jsonb),
  ('state-url-state', array['a']::text[], '{"en":"The URL is shareable, bookmarkable and survives reloads and back/forward navigation. Read filters from it (e.g. `useSearchParams`) as the single source of truth, rather than syncing a separate copy.","uk":"URL можна поширювати, додавати в закладки, і він переживає перезавантаження та навігацію назад/вперед. Читайте фільтри з нього (наприклад, `useSearchParams`) як із єдиного джерела правди, а не синхронізуйте окрему копію."}'::jsonb, null::jsonb),
  ('state-memoized-selector', array['a']::text[], '{"en":"`useSelector` compares the result with `===`. A fresh array is never equal to the previous one, so every dispatch triggers a render. A memoised selector returns the same array until `state.items` actually changes. Alternatively, select raw data and derive it in `useMemo`.","uk":"`useSelector` порівнює результат через `===`. Новий масив ніколи не дорівнює попередньому, тож кожне надсилання дії спричиняє рендер. Мемоізований селектор повертає той самий масив, доки `state.items` справді не зміниться. Як варіант, вибирайте сирі дані й обчислюйте похідні в `useMemo`."}'::jsonb, null::jsonb),
  ('state-cart-reducer', null::text[], '{"en":"Every branch returns new objects only along the changed path: `map` copies the one updated line and keeps the others by reference, `filter` and spread create new arrays, and nothing touches the old state. No-op actions return the original object so `===` checks skip work. The total is derived by a selector instead of being stored.","uk":"Кожна гілка повертає нові об''єкти лише вздовж зміненого шляху: `map` копіює один оновлений рядок і зберігає інші за посиланням, `filter` і spread створюють нові масиви, а старий стан ніхто не чіпає. Дії, що нічого не змінюють, повертають початковий об''єкт, щоб перевірки `===` пропускали роботу. Сума обчислюється селектором, а не зберігається."}'::jsonb, '{"/src/cart.ts":"export type Item = { id: string; name: string; price: number };\nexport type Line = Item & { qty: number };\nexport type Cart = { items: Line[] };\nexport type Action =\n  | { type: \"add\"; item: Item }\n  | { type: \"remove\"; id: string }\n  | { type: \"setQty\"; id: string; qty: number }\n  | { type: \"clear\" };\n\nexport const initialCart: Cart = { items: [] };\n\nexport function cartReducer(state: Cart, action: Action): Cart {\n  switch (action.type) {\n    case \"add\": {\n      const exists = state.items.some((l) => l.id === action.item.id);\n      return {\n        ...state,\n        items: exists\n          ? state.items.map((l) => (l.id === action.item.id ? { ...l, qty: l.qty + 1 } : l))\n          : [...state.items, { ...action.item, qty: 1 }],\n      };\n    }\n    case \"remove\": {\n      if (!state.items.some((l) => l.id === action.id)) return state;\n      return { ...state, items: state.items.filter((l) => l.id !== action.id) };\n    }\n    case \"setQty\": {\n      if (action.qty <= 0) return cartReducer(state, { type: \"remove\", id: action.id });\n      if (!state.items.some((l) => l.id === action.id)) return state;\n      return { ...state, items: state.items.map((l) => (l.id === action.id ? { ...l, qty: action.qty } : l)) };\n    }\n    case \"clear\":\n      return state.items.length ? { ...state, items: [] } : state;\n    default:\n      return state;\n  }\n}\n\nexport function selectTotal(state: Cart): number {\n  return state.items.reduce((sum, l) => sum + l.price * l.qty, 0);\n}\n"}'::jsonb),
  ('ts-as-const', array['c']::text[], '{"en":"`as const` stops literal widening and makes the result deeply readonly, so an array literal becomes a readonly tuple of literal types. `typeof directions[number]` then gives the union `\"up\" | \"down\"`, a common way to derive a union from a list of values.","uk":"`as const` вимикає розширення літералів і робить результат глибоко readonly, тож літерал масиву стає readonly-кортежем літеральних типів. Тоді `typeof directions[number]` дає об''єднання `\"up\" | \"down\"` — поширений спосіб вивести union зі списку значень."}'::jsonb, null::jsonb),
  ('ts-distributive-conditional', array['b']::text[], '{"en":"A conditional type whose checked type is a naked type parameter distributes over unions: `ToArray<string | number>` becomes `ToArray<string> | ToArray<number>`. To get `(string | number)[]` instead, wrap both sides in a tuple: `[T] extends [unknown] ? T[] : never`.","uk":"Умовний тип, у якому перевіряється «голий» параметр типу, розподіляється по об''єднанню: `ToArray<string | number>` стає `ToArray<string> | ToArray<number>`. Щоб отримати `(string | number)[]`, обгорніть обидві сторони в кортеж: `[T] extends [unknown] ? T[] : never`."}'::jsonb, null::jsonb),
  ('ts-function-variance', array['b']::text[], '{"en":"Function-type parameters are checked contravariantly: a handler that accepts any `Event` can stand in for one that expects a `MouseEvent` (`a` is fine), but not the reverse (`b` errors, since it could receive a `KeyboardEvent`). Method-shorthand members are deliberately exempt and stay bivariant, so `c` compiles even though it''s equally unsafe. Prefer property syntax (`handle: (e: Event) => void`) when you want the strict check.","uk":"Параметри типів-функцій перевіряються контраваріантно: обробник, що приймає будь-яку `Event`, може замінити той, що очікує `MouseEvent` (`a` коректне), але не навпаки (`b` — помилка, бо він може отримати `KeyboardEvent`). Члени, оголошені як методи, свідомо винятки й лишаються біваріантними, тож `c` компілюється, хоч воно так само небезпечне. Якщо потрібна строга перевірка, оголошуйте властивістю (`handle: (e: Event) => void`)."}'::jsonb, null::jsonb),
  ('ts-schema-validator', null::text[], '{"en":"Every schema is a small object with a `parse` closure, and composite schemas call their children''s `parse` with an extended path (`path.key`, `path[i]`). A shared `fail(): never` helper keeps the ternaries well-typed. `object` builds a fresh output from the shape''s keys only, which is what strips unknown keys, and `Infer` lets callers derive static types from the runtime schema.","uk":"Кожна схема — невеликий об''єкт із замиканням `parse`, а складені схеми викликають `parse` дочірніх із подовженим шляхом (`path.key`, `path[i]`). Спільний хелпер `fail(): never` зберігає коректну типізацію тернарних виразів. `object` будує новий результат лише з ключів форми — саме це відкидає невідомі ключі, а `Infer` дозволяє виводити статичні типи з runtime-схеми."}'::jsonb, '{"/src/schema.ts":"export class ValidationError extends Error {\n  path: string;\n  constructor(path: string, message: string) {\n    super((path || \"value\") + \": \" + message);\n    this.name = \"ValidationError\";\n    this.path = path;\n  }\n}\n\nexport type Schema<T> = { parse(value: unknown, path?: string): T };\nexport type Infer<S> = S extends Schema<infer T> ? T : never;\n\nfunction kind(value: unknown) {\n  if (value === null) return \"null\";\n  if (Array.isArray(value)) return \"array\";\n  if (Number.isNaN(value)) return \"NaN\";\n  return typeof value;\n}\n\nfunction fail(path: string, expected: string, value: unknown): never {\n  throw new ValidationError(path, \"expected \" + expected + \", got \" + kind(value));\n}\n\nexport function string(): Schema<string> {\n  return { parse: (value, path = \"\") => (typeof value === \"string\" ? value : fail(path, \"string\", value)) };\n}\n\nexport function number(): Schema<number> {\n  return {\n    parse: (value, path = \"\") => (typeof value === \"number\" && !Number.isNaN(value) ? value : fail(path, \"number\", value)),\n  };\n}\n\nexport function optional<T>(schema: Schema<T>): Schema<T | undefined> {\n  return { parse: (value, path) => (value === undefined ? undefined : schema.parse(value, path)) };\n}\n\nexport function array<T>(item: Schema<T>): Schema<T[]> {\n  return {\n    parse(value, path = \"\") {\n      if (!Array.isArray(value)) return fail(path, \"array\", value);\n      return value.map((entry, i) => item.parse(entry, path + \"[\" + i + \"]\"));\n    },\n  };\n}\n\nexport function object<S extends Record<string, Schema<unknown>>>(shape: S): Schema<{ [K in keyof S]: Infer<S[K]> }> {\n  return {\n    parse(value, path = \"\") {\n      if (typeof value !== \"object\" || value === null || Array.isArray(value)) return fail(path, \"object\", value);\n      const input = value as Record<string, unknown>;\n      const out: Record<string, unknown> = {};\n      for (const key of Object.keys(shape)) {\n        const parsed = shape[key].parse(input[key], path ? path + \".\" + key : key);\n        if (parsed !== undefined || key in input) out[key] = parsed;\n      }\n      return out as { [K in keyof S]: Infer<S[K]> };\n    },\n  };\n}\n"}'::jsonb),
  ('ts-unknown-vs-any', array['a']::text[], '{"en":"Both accept any value, but `unknown` is type-safe: you can''t call methods or access properties until you narrow it with `typeof`, `instanceof` or a type guard. `any` silently turns off checking and spreads.","uk":"Обидва приймають будь-яке значення, але `unknown` безпечний: не можна викликати методи чи читати властивості, доки ви не звузите тип через `typeof`, `instanceof` або type guard. `any` непомітно вимикає перевірку й поширюється."}'::jsonb, null::jsonb),
  ('ts-structural-typing', array['b']::text[], '{"en":"Line 3 assigns a variable that has extra properties, which is allowed because shapes are compatible. Line 4 assigns an object literal directly, so TypeScript runs an excess property check and rejects `z`.","uk":"Рядок 3 присвоює змінну із зайвими властивостями, і це дозволено, бо форми сумісні. Рядок 4 присвоює об''єктний літерал напряму, тож TypeScript перевіряє зайві властивості й відхиляє `z`."}'::jsonb, null::jsonb),
  ('ts-generic-constraint', array['a']::text[], '{"en":"`keyof T` is the union of T''s property names, and the constraint limits `K` to that union. That''s why `T[K]` is a valid, precise return type. It says nothing about runtime: an object typed as T could still miss the key.","uk":"`keyof T` є об''єднанням назв властивостей T, і обмеження зводить `K` до цього об''єднання. Тому `T[K]` є коректним і точним типом результату. Про час виконання це нічого не каже: об''єкт типу T все одно може не мати ключа."}'::jsonb, null::jsonb),
  ('ts-utility-types', array['a']::text[], '{"en":"`Omit<User, \"id\">` drops the key, and `Partial<…>` makes the rest optional. (`Omit<Partial<User>, \"id\">` would also work; the `| undefined` key in option B makes no sense.)","uk":"`Omit<User, \"id\">` прибирає ключ, а `Partial<…>` робить решту необов''язковими. (`Omit<Partial<User>, \"id\">` теж спрацював би; ключ `| undefined` у варіанті B не має сенсу.)"}'::jsonb, null::jsonb),
  ('ts-exhaustive-never', array['b']::text[], '{"en":"In the `default` branch the type of `s` is narrowed to whatever variants remain. With all cases handled that is `never`. After adding `triangle` it is the triangle type, which is not assignable to `never`, so the compiler points you to the missing case.","uk":"У гілці `default` тип `s` звужується до варіантів, що залишилися. Коли всі випадки оброблено, це `never`. Після додавання `triangle` це тип трикутника, який не можна присвоїти `never`, тож компілятор вкаже на пропущений випадок."}'::jsonb, null::jsonb),
  ('ts-typed-event-emitter', null::text[], '{"en":"Keep a `Map<event, Set<handler>>`. A Set preserves insertion order and makes `off` O(1). `on` returns a closure that calls `off`. In `emit`, iterate over a copy, so handlers that subscribe or unsubscribe during the loop don''t skip or repeat calls.","uk":"Зберігайте `Map<подія, Set<обробник>>`. Set зберігає порядок вставки й робить `off` за O(1). `on` повертає замикання, що викликає `off`. У `emit` проходьте по копії, щоб обробники, які підписуються чи відписуються під час циклу, не пропускали й не повторювали викликів."}'::jsonb, '{"/src/emitter.ts":"type Handler<P> = (payload: P) => void;\n\nexport function createEmitter<Events extends Record<string, unknown>>() {\n  const handlers = new Map<keyof Events, Set<Handler<any>>>();\n\n  function on<E extends keyof Events>(event: E, handler: Handler<Events[E]>): () => void {\n    if (!handlers.has(event)) handlers.set(event, new Set());\n    handlers.get(event)!.add(handler);\n    return () => off(event, handler);\n  }\n\n  function off<E extends keyof Events>(event: E, handler: Handler<Events[E]>): void {\n    handlers.get(event)?.delete(handler);\n  }\n\n  function emit<E extends keyof Events>(event: E, payload: Events[E]): void {\n    // Copy first, so (un)subscribing during emit doesn''t affect this round.\n    for (const handler of [...(handlers.get(event) ?? [])]) handler(payload);\n  }\n\n  return { on, off, emit };\n}\n"}'::jsonb),
  ('test-aaa', array['a']::text[], '{"en":"Unit tests should run in milliseconds, not depend on each other or on external services, give the same result every run, and fail for exactly one reason. The Arrange–Act–Assert structure helps: set up the inputs, call the code once, then check the outcome. Real databases belong in integration tests.","uk":"Модульні тести мають виконуватися за мілісекунди, не залежати один від одного чи від зовнішніх сервісів, давати той самий результат щоразу й падати рівно з однієї причини. Допомагає структура Arrange–Act–Assert: підготуйте вхідні дані, викличте код один раз, потім перевірте результат. Справжні бази даних — для інтеграційних тестів."}'::jsonb, null::jsonb),
  ('test-order-dependence', array['b']::text[], '{"en":"Order-dependent failures nearly always mean an earlier test changed shared state and didn''t restore it: a cached singleton, a spy that wasn''t restored, fake timers left on, or leftover DOM. Create fresh state in `beforeEach`, restore mocks in `afterEach` (or enable `restoreMocks` in the config), and run tests in random order to surface hidden coupling.","uk":"Падіння, залежні від порядку, майже завжди означають, що попередній тест змінив спільний стан і не відновив його: закешований синглтон, невідновлений шпигун, увімкнені фейкові таймери чи залишки DOM. Створюйте свіжий стан у `beforeEach`, відновлюйте моки в `afterEach` (або увімкніть `restoreMocks` у конфігурації) і запускайте тести у випадковому порядку, щоб виявити приховані зв''язки."}'::jsonb, null::jsonb),
  ('test-mutation', array['b']::text[], '{"en":"Coverage only proves code was executed. Mutation testing proves the tests notice when the code changes. A surviving boundary mutant means there''s no assertion at the edge, so add a test for exactly 18 (and 17). Some mutants are equivalent (no behaviour change) and can be ignored, but this one isn''t.","uk":"Покриття доводить лише те, що код виконувався. Мутаційне тестування доводить, що тести помічають зміну коду. Мутант межі, що вижив, означає відсутність перевірки на краю, тож додайте тест рівно для 18 (і 17). Деякі мутанти еквівалентні (поведінка не змінюється), їх можна ігнорувати, але цей — ні."}'::jsonb, null::jsonb),
  ('test-fake-clock', null::text[], '{"en":"Store each timer with an absolute due time and a monotonically increasing id. `tick` repeatedly picks the earliest due timer within the target time (the id breaks ties), sets the clock to its due time and runs it. Because the timer list is re-read on every step, timers that callbacks schedule are picked up within the same tick. This is what `vi.useFakeTimers()` and `jest.useFakeTimers()` do under the hood, using a heap for efficiency.","uk":"Зберігайте кожен таймер з абсолютним часом спрацювання й монотонно зростаючим id. `tick` раз за разом обирає найраніший таймер у межах цільового часу (id розв''язує рівність), встановлює годинник на його час і запускає. Оскільки список таймерів перечитується на кожному кроці, таймери, заплановані колбеками, підхоплюються в тому самому tick. Саме це під капотом роблять `vi.useFakeTimers()` і `jest.useFakeTimers()`, використовуючи купу для ефективності."}'::jsonb, '{"/src/fake-clock.ts":"export type FakeClock = {\n  now(): number;\n  setTimeout(fn: () => void, ms: number): number;\n  clearTimeout(id: number): void;\n  tick(ms: number): void;\n};\n\ntype Timer = { id: number; due: number; fn: () => void };\n\nexport function createFakeClock(): FakeClock {\n  let time = 0;\n  let nextId = 1;\n  let timers: Timer[] = [];\n\n  return {\n    now: () => time,\n    setTimeout(fn, ms) {\n      const id = nextId++;\n      timers.push({ id, due: time + Math.max(0, ms), fn });\n      return id;\n    },\n    clearTimeout(id) {\n      timers = timers.filter((timer) => timer.id !== id);\n    },\n    tick(ms) {\n      const end = time + ms;\n      for (;;) {\n        // Earliest due time first; ids increase, so they break ties in scheduling order.\n        let next: Timer | undefined;\n        for (const timer of timers) {\n          if (timer.due <= end && (!next || timer.due < next.due || (timer.due === next.due && timer.id < next.id))) next = timer;\n        }\n        if (!next) break;\n        const run = next;\n        timers = timers.filter((timer) => timer !== run);\n        time = run.due;\n        run.fn();\n      }\n      time = end;\n    },\n  };\n}\n"}'::jsonb),
  ('test-missing-await', array['a']::text[], '{"en":"The test function returns synchronously, the runner marks it as passed, and the assertion (or rejection) happens later. Use `async` + `await`, return the promise, or `await expect(p).resolves/rejects`.","uk":"Тестова функція повертається синхронно, раннер позначає її пройденою, а перевірка (чи відхилення) відбувається пізніше. Використайте `async` + `await`, поверніть проміс або `await expect(p).resolves/rejects`."}'::jsonb, null::jsonb),
  ('test-doubles', array['c']::text[], '{"en":"A fake has a working (simplified) implementation. A stub only returns canned answers, a spy/mock records calls for assertions, and fixtures are prepared test data.","uk":"Фейк має робочу (спрощену) реалізацію. Стаб лише повертає заготовлені відповіді, spy/mock записує виклики для перевірок, а фікстури є підготовленими тестовими даними."}'::jsonb, null::jsonb),
  ('test-query-priority', array['a']::text[], '{"en":"Role + accessible name is how users and assistive technology perceive the UI, and it survives refactors of classes and structure. Test IDs are a fallback, and class or position selectors couple tests to implementation details.","uk":"Роль + доступне ім''я відповідають тому, як інтерфейс сприймають користувачі й допоміжні технології, і це переживає рефакторинг класів і структури. Test ID є запасним варіантом, а селектори за класами чи позицією прив''язують тести до деталей реалізації."}'::jsonb, null::jsonb),
  ('test-fake-timers', array['a']::text[], '{"en":"Fake timers (`vi.useFakeTimers()` + `vi.advanceTimersByTime(30_000)`) make time-dependent tests instant and deterministic. Alternatively, inject the delay or a scheduler into the function.","uk":"Фейкові таймери (`vi.useFakeTimers()` + `vi.advanceTimersByTime(30_000)`) роблять тести, що залежать від часу, миттєвими й детермінованими. Як варіант, впровадьте затримку чи планувальник у функцію."}'::jsonb, null::jsonb),
  ('test-coverage-meaning', array['a']::text[], '{"en":"Coverage measures execution, not verification: a test without assertions still covers lines. Branch coverage, mutation testing and thoughtful edge cases say more about test quality.","uk":"Покриття вимірює виконання, а не перевірку: тест без перевірок усе одно покриває рядки. Покриття гілок, мутаційне тестування й продумані граничні випадки більше говорять про якість тестів."}'::jsonb, null::jsonb),
  ('test-injectable-reminders', null::text[], '{"en":"Injecting `now` and `send` makes the function deterministic and observable in tests: a fixed clock pins the 30-day boundary (exactly 30 days is not \"more than\"), and a mock `send` records calls and can simulate failures. A `for…of` loop with `await` sends sequentially, and `try/catch` per user isolates failures.","uk":"Впровадження `now` і `send` робить функцію детермінованою й спостережуваною в тестах: фіксований годинник закріплює межу 30 днів (рівно 30 днів не є «більше ніж»), а мок `send` записує виклики й може імітувати збої. Цикл `for…of` з `await` надсилає послідовно, а `try/catch` для кожного користувача ізолює збої."}'::jsonb, '{"/src/reminders.ts":"export type User = { email: string; lastActiveAt: number; optOut?: boolean };\nexport type Deps = { now: () => number; send: (email: string, message: string) => Promise<void> };\n\nexport const DAY = 24 * 60 * 60 * 1000;\n\nexport async function sendReminders(users: User[], deps: Deps): Promise<{ sent: string[]; failed: string[] }> {\n  const cutoff = deps.now() - 30 * DAY;\n  const sent: string[] = [];\n  const failed: string[] = [];\n\n  for (const user of users) {\n    if (user.optOut || user.lastActiveAt >= cutoff) continue;\n    try {\n      await deps.send(user.email, \"We miss you!\");\n      sent.push(user.email);\n    } catch {\n      failed.push(user.email);\n    }\n  }\n  return { sent, failed };\n}\n"}'::jsonb),
  ('a11y-aria-hidden-focusable', array['b']::text[], '{"en":"`aria-hidden` removes content from the accessibility tree but doesn''t stop keyboard focus, which leaves focusable elements that screen readers can''t describe. Use the `inert` attribute (it removes the content from both focus and the accessibility tree), or hide it with `display: none` / `hidden` when closed.","uk":"`aria-hidden` прибирає вміст із дерева доступності, але не блокує фокус клавіатури, тож лишаються фокусовані елементи, які зчитувачі екрана не можуть описати. Використовуйте атрибут `inert` (він прибирає вміст і з фокусу, і з дерева доступності) або ховайте панель через `display: none` / `hidden`, коли вона закрита."}'::jsonb, null::jsonb),
  ('a11y-name-precedence', array['c']::text[], '{"en":"The accessible name algorithm checks `aria-labelledby` first, then `aria-label`, then native labelling (content, `<label>`, `alt`), and `title` last. `aria-labelledby` wins here, so the name is the text of `#draft-title`. Keep the visible label inside the accessible name so speech-control users can say what they see (WCAG 2.5.3).","uk":"Алгоритм доступної назви спершу перевіряє `aria-labelledby`, далі `aria-label`, далі нативні мітки (вміст, `<label>`, `alt`), а `title` — останнім. Тут перемагає `aria-labelledby`, тож назва — це текст `#draft-title`. Тримайте видиму мітку в доступній назві, щоб користувачі голосового керування могли назвати те, що бачать (WCAG 2.5.3)."}'::jsonb, null::jsonb),
  ('a11y-focus-not-obscured', array['b']::text[], '{"en":"2.4.11 Focus Not Obscured (Minimum, AA) requires that a focused component is not entirely hidden by author-created content such as sticky headers or cookie banners. `scroll-padding-top` on the scroll container makes the browser leave room at the top when it scrolls focused elements into view. The outline is visible here; it''s just covered.","uk":"2.4.11 Focus Not Obscured (Minimum, AA) вимагає, щоб компонент із фокусом не був повністю схований вмістом автора, як-от липкими заголовками чи банерами cookie. `scroll-padding-top` на контейнері прокрутки змушує браузер лишати місце зверху, коли він прокручує елементи з фокусом у видиму область. Рамка тут видима — її просто перекрито."}'::jsonb, null::jsonb),
  ('a11y-roving-tabindex', null::text[], '{"en":"A roving tabindex keeps composite widgets to a single Tab stop: the active item gets `tabindex=\"0\"` and all the others get `-1`, so Tab moves past the toolbar while the arrow keys move within it. One delegated `keydown` listener maps keys to target indexes, and modulo arithmetic handles the wrapping. Handled keys call `preventDefault()` so arrows don''t also scroll the page.","uk":"Roving tabindex зводить складені віджети до однієї зупинки Tab: активний елемент отримує `tabindex=\"0\"`, а всі інші — `-1`, тож Tab проходить повз панель, а стрілки рухаються всередині неї. Один делегований обробник `keydown` зіставляє клавіші з цільовими індексами, а арифметика за модулем забезпечує перехід по колу. Оброблені клавіші викликають `preventDefault()`, щоб стрілки ще й не прокручували сторінку."}'::jsonb, '{"/src/toolbar.ts":"export function initToolbar(toolbar: HTMLElement): void {\n  const buttons = Array.from(toolbar.querySelectorAll<HTMLButtonElement>(\"button\"));\n  if (buttons.length === 0) return;\n\n  const makeTabStop = (target: HTMLButtonElement) => {\n    for (const button of buttons) button.tabIndex = button === target ? 0 : -1;\n  };\n  const focusAt = (index: number) => {\n    const target = buttons[(index + buttons.length) % buttons.length];\n    makeTabStop(target);\n    target.focus();\n  };\n\n  makeTabStop(buttons[0]);\n\n  toolbar.addEventListener(\"keydown\", (event) => {\n    const current = buttons.indexOf(document.activeElement as HTMLButtonElement);\n    if (current === -1) return;\n    const moves: Record<string, number> = {\n      ArrowRight: current + 1,\n      ArrowLeft: current - 1,\n      Home: 0,\n      End: buttons.length - 1,\n    };\n    if (!(event.key in moves)) return;\n    event.preventDefault();\n    focusAt(moves[event.key]);\n  });\n\n  toolbar.addEventListener(\"click\", (event) => {\n    const button = (event.target as HTMLElement).closest(\"button\");\n    if (button && buttons.includes(button as HTMLButtonElement)) makeTabStop(button as HTMLButtonElement);\n  });\n}\n"}'::jsonb),
  ('a11y-first-rule', array['a']::text[], '{"en":"ARIA changes semantics, not behaviour. You''d still need `tabindex=\"0\"`, key handlers and focus styles. That''s why the first rule of ARIA is to use the native element (`<button>`) whenever possible.","uk":"ARIA змінює семантику, а не поведінку. Вам усе одно знадобляться `tabindex=\"0\"`, обробники клавіш і стилі фокусу. Тому перше правило ARIA: використовувати нативний елемент (`<button>`), коли це можливо."}'::jsonb, null::jsonb),
  ('a11y-icon-button', array['a']::text[], '{"en":"`aria-label` (or visually hidden text) names the button, and `aria-hidden` on the decorative SVG prevents noise. A div isn''t a button, and an empty title gives no name.","uk":"`aria-label` (або візуально прихований текст) дає кнопці ім''я, а `aria-hidden` на декоративному SVG прибирає зайвий шум. Div не є кнопкою, а порожній title не дає імені."}'::jsonb, null::jsonb),
  ('a11y-contrast', array['b']::text[], '{"en":"AA requires 4.5:1 for normal text and 3:1 for large text (≈24px regular or 18.66px bold) and for UI component boundaries and focus indicators. 7:1 is the stricter AAA level.","uk":"AA вимагає 4,5:1 для звичайного тексту і 3:1 для великого (≈24px звичайного чи 18,66px жирного), а також для меж елементів інтерфейсу й індикаторів фокусу. 7:1 є суворішим рівнем AAA."}'::jsonb, null::jsonb),
  ('a11y-modal-focus', array['a', 'b', 'c']::text[], '{"en":"Keyboard and screen-reader users must land in the dialog, not tab into the page behind it, and get back where they were afterwards. The native `<dialog>` with `showModal()` provides inertness and Escape handling. Removing focus outlines breaks WCAG 2.4.7.","uk":"Користувачі клавіатури й зчитувачів екрана мають потрапити в діалог, а не переходити Tab на сторінку під ним, і після закриття повернутися туди, де були. Нативний `<dialog>` із `showModal()` забезпечує інертність фону й обробку Escape. Прибрання обведення фокусу порушує WCAG 2.4.7."}'::jsonb, null::jsonb),
  ('a11y-live-region', array['a']::text[], '{"en":"Live regions are announced when their content changes, but the region must already be in the DOM, otherwise some screen readers miss the first update. Use `polite` for non-urgent status and `role=\"alert\"` (assertive) for errors.","uk":"Живі регіони оголошуються, коли змінюється їхній вміст, але сам регіон має вже бути в DOM, інакше деякі зчитувачі пропустять перше оновлення. Використовуйте `polite` для нетермінових статусів і `role=\"alert\"` (assertive) для помилок."}'::jsonb, null::jsonb),
  ('a11y-accessible-switch', null::text[], '{"en":"`role=\"switch\"` with `aria-checked` tells assistive technology what the control is and its state, `aria-label` names it, and `tabIndex = 0` puts it in the tab order. Because ARIA adds no behaviour, you wire up Space and Enter yourself and prevent Space''s default scroll. Keeping state in `aria-checked` lets CSS style `[aria-checked=\"true\"]` from a single source of truth. A native `<button aria-pressed>` or `<input type=\"checkbox\" role=\"switch\">` would need less code.","uk":"`role=\"switch\"` разом з `aria-checked` повідомляє допоміжним технологіям, що це за елемент і в якому він стані, `aria-label` дає ім''я, а `tabIndex = 0` додає його в порядок табуляції. Оскільки ARIA не додає поведінки, Space і Enter треба під''єднати самостійно та скасувати прокрутку від Space. Стан в `aria-checked` дозволяє CSS стилізувати `[aria-checked=\"true\"]` з одного джерела правди. Нативні `<button aria-pressed>` або `<input type=\"checkbox\" role=\"switch\">` потребували б менше коду."}'::jsonb, '{"/src/switch.js":"export function enhanceSwitch(el, onChange) {\n  el.setAttribute(\"role\", \"switch\");\n  el.setAttribute(\"aria-label\", el.dataset.label ?? \"\");\n  el.setAttribute(\"aria-checked\", \"false\");\n  el.tabIndex = 0;\n\n  function toggle() {\n    const checked = el.getAttribute(\"aria-checked\") !== \"true\";\n    el.setAttribute(\"aria-checked\", String(checked));\n    onChange(checked);\n  }\n\n  el.addEventListener(\"click\", toggle);\n  el.addEventListener(\"keydown\", (event) => {\n    if (event.key === \" \" || event.key === \"Enter\") {\n      event.preventDefault(); // Space would otherwise scroll the page\n      toggle();\n    }\n  });\n}\n"}'::jsonb),
  ('perf-font-display', array['b']::text[], '{"en":"`swap` renders text in the fallback font right away and swaps in the web font when it loads, so text is never invisible (FOIT). Reduce the resulting layout shift by preloading the main font and tuning the fallback with `size-adjust`. `block` is the behaviour that hides text.","uk":"`swap` одразу рендерить текст резервним шрифтом і підміняє вебшрифт після завантаження, тож текст ніколи не буває невидимим (FOIT). Зменште зсув макета, що виникає, попереднім завантаженням основного шрифту й налаштуванням резервного через `size-adjust`. `block` — саме та поведінка, що ховає текст."}'::jsonb, null::jsonb),
  ('perf-content-visibility', array['a']::text[], '{"en":"`content-visibility: auto` skips rendering work for off-screen elements while keeping them in the DOM and accessibility tree, so find-in-page and anchor links still work. `contain-intrinsic-size` gives a placeholder size, so the scrollbar doesn''t jump. `display: none` removes content from the accessibility tree, and `will-change` adds layers instead of saving work.","uk":"`content-visibility: auto` пропускає роботу з рендерингу для елементів поза екраном, залишаючи їх у DOM і дереві доступності, тож пошук на сторінці та якорі працюють. `contain-intrinsic-size` задає розмір-заглушку, щоб смуга прокрутки не стрибала. `display: none` прибирає вміст із дерева доступності, а `will-change` додає шари замість економії роботи."}'::jsonb, null::jsonb),
  ('perf-detached-dom', array['b']::text[], '{"en":"Repeat the action several times so the leak stands out from one-time caches, then use the Memory panel''s comparison view or filter for \"Detached\". The retainers path shows what still references the removed nodes: typically a global listener, a timer, a cache map or a closure. Lighthouse measures page loads, not leaks during interaction.","uk":"Повторіть дію кілька разів, щоб витік вирізнявся на тлі одноразових кешів, потім скористайтеся порівнянням у панелі Memory або фільтром «Detached». Шлях утримувачів показує, що досі посилається на видалені вузли: зазвичай глобальний обробник, таймер, кеш-мапа чи замикання. Lighthouse вимірює завантаження сторінки, а не витоки під час взаємодії."}'::jsonb, null::jsonb),
  ('perf-throttle', null::text[], '{"en":"The closure tracks two things: whether a window is open (`timer`) and the latest arguments received during it. A call with no open window runs immediately and opens one. Calls during the window only overwrite `pendingArgs`. When the window ends, a pending call runs and opens a new window, so `fn` never runs more often than once per `wait`. Debounce waits for silence; throttle guarantees a steady rate.","uk":"Замикання відстежує дві речі: чи відкрите вікно (`timer`) і останні аргументи, отримані в ньому. Виклик без відкритого вікна виконується одразу й відкриває вікно. Виклики під час вікна лише перезаписують `pendingArgs`. Коли вікно закінчується, відкладений виклик виконується й відкриває нове вікно, тож `fn` ніколи не запускається частіше ніж раз на `wait`. Debounce чекає на тишу; throttle гарантує рівномірну частоту."}'::jsonb, '{"/src/throttle.ts":"export type Throttled<A extends unknown[]> = ((...args: A) => void) & { cancel(): void };\n\nexport function throttle<A extends unknown[]>(fn: (...args: A) => void, wait: number): Throttled<A> {\n  let timer: ReturnType<typeof setTimeout> | undefined;\n  let pendingArgs: A | undefined;\n\n  const endWindow = () => {\n    if (pendingArgs) {\n      const args = pendingArgs;\n      pendingArgs = undefined;\n      fn(...args);\n      timer = setTimeout(endWindow, wait); // the trailing call opens a new window\n    } else {\n      timer = undefined;\n    }\n  };\n\n  const throttled = (...args: A) => {\n    if (timer === undefined) {\n      fn(...args);\n      timer = setTimeout(endWindow, wait);\n    } else {\n      pendingArgs = args;\n    }\n  };\n\n  return Object.assign(throttled, {\n    cancel() {\n      clearTimeout(timer);\n      timer = undefined;\n      pendingArgs = undefined;\n    },\n  });\n}\n"}'::jsonb),
  ('perf-core-web-vitals', array['b']::text[], '{"en":"Interaction to Next Paint measures the delay from user input to the next frame being painted. LCP is about loading the main content, CLS about unexpected layout shifts, and TTFB about server response time.","uk":"Interaction to Next Paint вимірює затримку від дії користувача до наступного відмальованого кадру. LCP стосується завантаження основного вмісту, CLS неочікуваних зсувів розкладки, а TTFB часу відповіді сервера."}'::jsonb, null::jsonb),
  ('perf-transform-animation', array['c']::text[], '{"en":"`left`, `width` and `margin` change geometry and trigger layout and paint on every frame. `transform` (and `opacity`) can be handled by the compositor, often on the GPU, without re-running layout.","uk":"`left`, `width` і `margin` змінюють геометрію й запускають layout і paint на кожному кадрі. `transform` (і `opacity`) може обробити композитор, часто на GPU, без повторного layout."}'::jsonb, null::jsonb),
  ('perf-cls-images', array['a']::text[], '{"en":"Without dimensions the browser allocates 0 height until the image arrives, then pushes content down, which is CLS. Intrinsic dimensions let it reserve the right box upfront. Lazy loading or smaller formats help loading time but not shifts.","uk":"Без розмірів браузер виділяє нульову висоту, доки зображення не завантажиться, а потім зсуває вміст донизу: це і є CLS. Власні розміри дозволяють одразу зарезервувати правильний блок. Ліниве завантаження чи менші формати пришвидшують завантаження, але не прибирають зсувів."}'::jsonb, null::jsonb),
  ('perf-debounce-vs-throttle', array['b']::text[], '{"en":"Throttle gives regular updates during a continuous stream of events. Debounce waits for a pause, which suits search-as-you-type or saving drafts. For scroll-linked visuals, `requestAnimationFrame` or IntersectionObserver are even better.","uk":"Throttle дає регулярні оновлення під час безперервного потоку подій. Debounce чекає на паузу, що підходить для пошуку під час введення чи збереження чернеток. Для візуальних ефектів, пов''язаних із прокруткою, ще краще підходять `requestAnimationFrame` або IntersectionObserver."}'::jsonb, null::jsonb),
  ('perf-long-task', array['a', 'b', 'd']::text[], '{"en":"A long synchronous task blocks input and paint. A worker moves it off the main thread, and chunking with yields lets the browser handle events between chunks. Painting feedback first makes the interaction feel immediate. An `async` function without `await` still runs synchronously.","uk":"Довга синхронна задача блокує введення й відмальовування. Воркер виносить її з головного потоку, а розбиття на частини з поступками дозволяє браузеру обробляти події між ними. Якщо спершу відмалювати відгук, взаємодія здається миттєвою. `async`-функція без `await` все одно виконується синхронно."}'::jsonb, null::jsonb),
  ('perf-debounce', null::text[], '{"en":"Keep the pending timer in a closure. Each call clears it and schedules a new one with the latest arguments, so only the call after a quiet period fires. Use a regular `function` (not an arrow) so `this` comes from the caller, then forward it with `apply`. `cancel` simply clears the timer.","uk":"Тримайте відкладений таймер у замиканні. Кожен виклик очищає його й планує новий з останніми аргументами, тож спрацьовує лише виклик після паузи. Використайте звичайну `function` (не стрілкову), щоб `this` брався від викликача, і передайте його через `apply`. `cancel` просто очищає таймер."}'::jsonb, '{"/src/debounce.ts":"export type Debounced<A extends unknown[]> = ((...args: A) => void) & { cancel(): void };\n\nexport function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number): Debounced<A> {\n  let timer: ReturnType<typeof setTimeout> | undefined;\n\n  const debounced = function (this: unknown, ...args: A) {\n    clearTimeout(timer);\n    timer = setTimeout(() => {\n      timer = undefined;\n      fn.apply(this, args);\n    }, wait);\n  } as Debounced<A>;\n\n  debounced.cancel = () => {\n    clearTimeout(timer);\n    timer = undefined;\n  };\n\n  return debounced;\n}\n"}'::jsonb)
) as v(task_slug, correct_option_ids, explanation, solution_files)
join public.tasks t on t.slug = v.task_slug and t.source = 'seed'
on conflict (task_id) do update set correct_option_ids = excluded.correct_option_ids,
  explanation = excluded.explanation, solution_files = excluded.solution_files;

update public.skills s set has_content = exists (
  select 1 from public.task_skills ts join public.tasks t on t.id = ts.task_id and t.published where ts.skill_id = s.id);

commit;
